      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        "User-Agent": "STONEMILES explore places lookup (OpenStreetMap Overpass)",
        Accept: "application/json"
      },
      body: `data=${encodeURIComponent(query)}`,
      signal: ctrl.signal
