// src/sealGrade.ts
var RELEASE_GRADE_GEOFENCE_MI = 0.25;
var GOOD_FIX_ACCURACY_M = 65;
var GOOD_FIX_MIN_GOOD_SHARE = 0.5;
function evaluateSealGrade(input) {
  const tightGeofence = {
    pass: input.distanceMi != null && input.distanceMi <= RELEASE_GRADE_GEOFENCE_MI,
    distanceMi: input.distanceMi,
    radiusMi: RELEASE_GRADE_GEOFENCE_MI
  };
  const bolFingerprinted = {
    pass: typeof input.bolSha256 === "string" && input.bolSha256.length > 0,
    sha256: input.bolSha256 ?? null
  };
  const docExceptions = input.openExceptionDetails ?? [];
  const exceptionDetails = [];
  if (input.sealMismatch) {
    exceptionDetails.push("the entered pickup seal number did not match the BOL seal number (seal mismatch on record)");
  }
  for (const d of docExceptions)
    exceptionDetails.push(d);
  const noOpenExceptions = {
    pass: exceptionDetails.length === 0,
    detail: exceptionDetails.length === 0 ? "No open exception flag on the load." : `Open exception${exceptionDetails.length === 1 ? "" : "s"}: ${exceptionDetails.join(" \xB7 ")}.`
  };
  let gpsFixQuality;
  if (!input.fixQuality) {
    gpsFixQuality = {
      pass: false,
      detail: "No sealed trip sheet with GPS fix-quality tallies for this load yet \u2014 fix quality unproven.",
      accepted: null,
      goodShare: null
    };
  } else {
    const fq = input.fixQuality;
    const totalRaw = fq.accLe10 + fq.accLe25 + fq.accLe50 + fq.accLe65 + fq.accGt65 + fq.accNone;
    const good = totalRaw - fq.accGt65 - fq.accNone;
    const goodShare = totalRaw > 0 ? Math.round(good / totalRaw * 1000) / 1000 : 0;
    if (fq.accepted < 1) {
      gpsFixQuality = {
        pass: false,
        detail: "The trip's GPS filter accepted no fixes \u2014 fix quality unproven.",
        accepted: fq.accepted,
        goodShare
      };
    } else if (goodShare < GOOD_FIX_MIN_GOOD_SHARE) {
      gpsFixQuality = {
        pass: false,
        detail: `Only ${Math.round(goodShare * 100)}% of the trip's GPS fixes met the ${GOOD_FIX_ACCURACY_M} m good-fix standard (needs at least ${Math.round(GOOD_FIX_MIN_GOOD_SHARE * 100)}%).`,
        accepted: fq.accepted,
        goodShare
      };
    } else {
      gpsFixQuality = {
        pass: true,
        detail: `${Math.round(goodShare * 100)}% of the trip's GPS fixes met the ${GOOD_FIX_ACCURACY_M} m good-fix standard; ${fq.accepted} fixes accepted.`,
        accepted: fq.accepted,
        goodShare
      };
    }
  }
  const criteria = {
    tightGeofence,
    bolFingerprinted,
    noOpenExceptions,
    gpsFixQuality
  };
  const allPass = criteria.tightGeofence.pass && criteria.bolFingerprinted.pass && criteria.noOpenExceptions.pass && criteria.gpsFixQuality.pass;
  return { grade: allPass ? "release_grade" : "proof_grade", criteria };
}

