// src/dispatchFee.ts
var DISPATCH_FEE_RATE = 0.1;
var COLLECTION_WINDOW_DAYS = 7;
var REVOKE_DAYS = 10;
var DISPATCH_FEE_CRYPTO_ADDRESS = "0x3a6fEBE311F98629C9A98452dB0968C315930447";
var DISPATCH_FEE_CARD_LINK = null;
var DAY_MS2 = 86400000;
var CENT_EPSILON = 0.005;
function roundCents(n) {
  return Math.round(n * 100) / 100;
}
function freightAmountFor(rate, extraCharges) {
  if (rate == null)
    return null;
  return roundCents(rate + (extraCharges ?? 0));
}
