// src/wzdx.ts
var WZDX_FEEDS = [
  {
    key: "wi511",
    url: "https://511wi.gov/api/wzdx",
    sourceLabel: "Wisconsin DOT \xB7 511WI",
    bbox: { minLat: 42.4, maxLat: 47.1, minLon: -92.9, maxLon: -86.7 }
  }
];
var WZDX_CACHE_MS = 10 * 60000;
var WZDX_NEAR_RADIUS_MI = 60;
function haversineMi2(lat1, lon1, lat2, lon2) {
  const R = 3958.8;
  const dLat = (lat2 - lat1) * Math.PI / 180;
  const dLon = (lon2 - lon1) * Math.PI / 180;
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(a)));
}
function wzdxPoint(geometry) {
  if (!geometry || typeof geometry !== "object")
    return null;
  const g = geometry;
  let pair = null;
  if (g.type === "Point")
    pair = g.coordinates;
  else if (g.type === "MultiPoint" || g.type === "LineString") {
    pair = Array.isArray(g.coordinates) ? g.coordinates[0] : null;
  }
  if (!Array.isArray(pair) || pair.length < 2)
    return null;
  const [lon, lat] = pair;
  if (typeof lat !== "number" || typeof lon !== "number" || !Number.isFinite(lat) || !Number.isFinite(lon))
    return null;
  if (lat < -90 || lat > 90 || lon < -180 || lon > 180)
    return null;
  return { lat, lon };
}
function parseWzdxFeed(feedJson, feed, nowMs) {
  if (!feedJson || typeof feedJson !== "object")
    return [];
  const features = feedJson.features;
  if (!Array.isArray(features))
    return [];
  const out = [];
  for (const f of features) {
    if (!f || typeof f !== "object")
      continue;
    const feat = f;
    const props = feat.properties ?? {};
    const startMs = typeof props.start_date === "string" ? Date.parse(props.start_date) : NaN;
    const endMs = typeof props.end_date === "string" ? Date.parse(props.end_date) : NaN;
    if (!Number.isFinite(startMs) || !Number.isFinite(endMs))
      continue;
    if (nowMs < startMs || nowMs > endMs)
      continue;
    const pt = wzdxPoint(feat.geometry);
    if (!pt)
      continue;
    const roads = props.core_details?.road_names;
    const namedRoads = Array.isArray(roads) && roads.every((r) => typeof r === "string") ? roads.filter((r) => r.trim() && r.trim().toLowerCase() !== "unknown") : [];
    const road = namedRoads.length > 0 ? namedRoads.join(" / ") : null;
    const desc = props.core_details?.description;
    out.push({
      id: `${feed.key}-${typeof feat.id === "string" && feat.id ? feat.id : `${pt.lat.toFixed(5)},${pt.lon.toFixed(5)}`}`,
      lat: pt.lat,
      lon: pt.lon,
      road,
      description: typeof desc === "string" && desc.trim() ? desc.trim().slice(0, 300) : null,
      startMs,
      endMs,
      sourceLabel: feed.sourceLabel
    });
  }
  return out;
}
function feedsForPosition(lat, lon) {
  const M = 0.5;
  return WZDX_FEEDS.filter((f) => lat >= f.bbox.minLat - M && lat <= f.bbox.maxLat + M && lon >= f.bbox.minLon - M && lon <= f.bbox.maxLon + M);
}
var feedCache = new Map;
var feedInFlight = new Map;
async function fetchFeedZones(feed) {
  const cached = feedCache.get(feed.key);
  if (cached && Date.now() - cached.fetchedAtMs < WZDX_CACHE_MS)
    return cached.zones;
  const inFlight = feedInFlight.get(feed.key);
  if (inFlight)
    return inFlight;
  const p = (async () => {
    try {
      const res = await fetch(feed.url, {
        headers: { "User-Agent": "STONEMILES work-zone layer (WZDx reader)", Accept: "application/json" },
        signal: AbortSignal.timeout(30000)
      });
      if (!res.ok)
        return null;
      const json = await res.json();
      const zones = parseWzdxFeed(json, feed, Date.now());
      feedCache.set(feed.key, { fetchedAtMs: Date.now(), zones });
      return zones;
    } catch {
      return null;
    } finally {
      feedInFlight.delete(feed.key);
    }
  })();
  feedInFlight.set(feed.key, p);
  return p;
}
