// src/permit.ts
function isIsoDate(value) {
  if (value == null)
    return false;
  const m = value.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m)
    return false;
  const y = Number(m[1]);
  const mo = Number(m[2]);
  const d = Number(m[3]);
  if (mo < 1 || mo > 12 || d < 1 || d > 31)
    return false;
  const dt = new Date(Date.UTC(y, mo - 1, d));
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === mo - 1 && dt.getUTCDate() === d;
}
