async function trainingStatusFor(ctx, username) {
  const db = ctx.db();
  const season = seasonInfo(Date.now());
  const completions = (await db.select().from(trainingCompletions3).where(eq(trainingCompletions3.username, username))).sort((a, b) => b.completedAt.getTime() - a.completedAt.getTime());
  const attempts = await db.select().from(trainingAttempts3).where(eq(trainingAttempts3.username, username));
  const courses = TRAINING_COURSES.map((c) => {
    const mine = completions.filter((x) => x.courseId === c.id);
    const thisSeason = mine.find((x) => x.seasonNumber === season.number);
    const latest = mine[0] ?? null;
    const myAttempts = attempts.filter((a) => a.courseId === c.id);
    const status = c.core ? thisSeason ? "current" : "due" : latest ? "current" : "not_started";
    return {
      courseId: c.id,
      core: c.core,
      status,
      completedEver: mine.length > 0,
      lastCompletedAt: latest?.completedAt.toISOString() ?? null,
      completedSeason: latest?.seasonNumber ?? null,
      attempts: myAttempts.length,
      bestScorePct: myAttempts.length > 0 ? Math.max(...myAttempts.map((a) => a.scorePct)) : null,
      sealedHash: (thisSeason ?? latest)?.chainHash ?? null
    };
  });
  return { courses, completions, season };
}
