async function appendChain(ctx, args) {
  return enqueueChain(async () => {
    const db = ctx.db();
    const last = await db.select({ hash: chainLog3.hash }).from(chainLog3).orderBy(desc(chainLog3.id)).limit(1);
    const prevHash = last[0]?.hash ?? GENESIS_HASH;
    const payload = JSON.stringify(args.payload);
    const hash = await sha256(`${prevHash}|${args.event}|${payload}`);
    await db.insert(chainLog3).values({
      refKind: args.refKind,
      refId: args.refId,
      sessionId: args.sessionId,
      event: args.event,
      payload,
      prevHash,
      hash
    });
    return hash;
  });
}
