async function docCopySettingsRow(ctx, username) {
  const db = ctx.db();
  const rows = await db.select().from(docCopySettings3).where(eq(docCopySettings3.username, username)).limit(1);
  if (rows[0])
    return rows[0];
  const legacy = await db.select().from(docCopySettings3).where(eq(docCopySettings3.username, "")).limit(1);
  const legacyRow = legacy[0];
  if (legacyRow) {
    await db.update(docCopySettings3).set({ username }).where(eq(docCopySettings3.id, legacyRow.id));
    return { ...legacyRow, username };
  }
  return null;
}
async function docEmailProviderConfigured(ctx) {
  try {
    const cfg = await ctx.executePrivileged(privileged.docEmailConfig, {});
    return cfg.configured;
  } catch {
    return false;
  }
}
async function resolveDocCopyRecipients(ctx, me) {
  const db = ctx.db();
  const settings = await docCopySettingsRow(ctx, me);
  const mine = await myMembership(ctx, me);
  let companyContactEmail = null;
  let dispatchUsernames = [];
  if (mine) {
    const members = await db.select().from(companyMembers3).where(eq(companyMembers3.companyId, mine.company.id));
    dispatchUsernames = members.filter((m) => m.role === "dispatch").map((m) => m.username);
    const setup = await db.select().from(companySetup3).where(eq(companySetup3.companyId, mine.company.id)).limit(1);
    companyContactEmail = setup[0]?.contactEmail ?? null;
  }
  const recipients = resolveDocRecipients({
    driverUsername: me,
    driverEmail: settings?.driverEmail ?? null,
    dispatchEmail: settings?.dispatchEmail ?? null,
    ownerEmailSetting: settings?.ownerEmail ?? null,
    companyContactEmail,
    ownerUsername: mine?.company.ownerUsername ?? null,
    dispatchUsernames,
    inCompany: mine != null
  });
  return { settings, recipients, inCompany: mine != null };
}
function docCopyEmailText(args) {
  return [
    "STONEMILES \u2014 confirmed document copy",
    "",
    args.label,
    `Load #${args.loadId}`,
    ...args.summaryLines,
    "",
    `Document fingerprint (SHA-256): ${args.sha256}`,
    args.hasAttachment ? "The document file is attached to this email." : "The sealed document itself is filed in the driver's STONEMILES Files (Loads \u2192 All loads \u2192 Filed document copies) and in the load's record.",
    "",
    "This copy was filed because the document was confirmed in STONEMILES. The sealed original lives in the load's record, fingerprinted into its hash chain."
  ].join(`
`);
}
async function fileConfirmedDocCopy(ctx, args) {
  const db = ctx.db();
  const me = await myUsername(ctx);
  const dedupeKey = args.dedupeKey ?? filedCopyDedupeKey(args.loadId, args.docKind, args.sha256);
  const existing = await db.select().from(filedDocCopies3).where(eq(filedDocCopies3.dedupeKey, dedupeKey)).limit(1);
  if (existing[0]) {
    return { ...NO_COPIES, filed: true };
  }
  const inserted = await db.insert(filedDocCopies3).values({
    loadId: args.loadId,
    docKind: args.docKind,
    label: args.label,
    blobKey: args.blobKey,
    ownsBlob: args.ownsBlob,
    mime: args.mime,
    sha256: args.sha256,
    source: args.source,
    filedBy: me,
    dedupeKey
  }).returning({ id: filedDocCopies3.id });
  const copyId = inserted[0]?.id ?? null;
  const { settings, recipients } = await resolveDocCopyRecipients(ctx, me);
  const enabled = settings?.enabled ?? true;
  const anyAddress = recipients.some((r) => r.email != null);
  const providerConfigured = enabled && anyAddress ? await docEmailProviderConfigured(ctx) : false;
  let sent = 0;
  let queued = 0;
  let noAddress = 0;
  for (const r of recipients) {
    const dKey = deliveryDedupeKey(dedupeKey, r.role);
    const dupe = await db.select().from(docEmailDeliveries3).where(eq(docEmailDeliveries3.dedupeKey, dKey)).limit(1);
    if (dupe[0])
      continue;
    const plan = planDeliveryStatus({ enabled, email: r.email, providerConfigured });
    let status = plan.status;
    let detail = plan.detail;
    let providerId = null;
    let sentAt = null;
    if (plan.status === "send" && r.email) {
      try {
        const res = await ctx.executePrivileged(privileged.sendDocEmail, {
          to: r.email,
          subject: `STONEMILES \u2014 ${args.label}`,
          text: docCopyEmailText({
            label: args.label,
            loadId: args.loadId,
            sha256: args.sha256,
            summaryLines: args.summaryLines,
            hasAttachment: args.attachmentBase64 != null
          }),
          attachmentBase64: args.attachmentBase64 ?? null,
          attachmentFilename: args.attachmentFilename ?? null
        });
        if (res.ok && res.providerId) {
          status = "sent";
          detail = args.attachmentBase64 ? "Sent through the connected mail provider, document file attached." : "Sent through the connected mail provider. The sealed document is filed in the driver's STONEMILES Files and in the load's record.";
          providerId = res.providerId;
          sentAt = new Date;
          sent++;
        } else if (res.notConfigured) {
          status = "queued";
          detail = planDeliveryStatus({ enabled: true, email: r.email, providerConfigured: false }).detail;
          queued++;
        } else {
          status = "failed";
          detail = `The mail provider refused this copy: ${res.errorMessage ?? "unknown error"}. It can be re-sent from Filed document copies.`;
        }
      } catch {
        status = "failed";
        detail = "The mail send didn't complete \u2014 it can be re-sent from Filed document copies.";
      }
    } else if (status === "queued") {
      queued++;
    } else if (status === "no_address") {
      noAddress++;
    }
    await db.insert(docEmailDeliveries3).values({
      loadId: args.loadId,
      filedCopyId: copyId,
      docKind: args.docKind,
      recipientRole: r.role,
      recipientEmail: r.email,
      recipientUsername: r.username,
      status,
      detail,
      providerId,
      dedupeKey: dKey,
      sentAt
    });
  }
  await appendChain(ctx, {
    refKind: "load",
    refId: args.loadId,
    sessionId: null,
    event: "doc_copies_filed",
    payload: {
      loadId: args.loadId,
      copyId,
      docKind: args.docKind,
      source: args.source,
      sha256: args.sha256,
      filedBy: me,
      sent,
      queued,
      noAddress,
      copiesOff: !enabled,
      at: new Date().toISOString()
    }
  });
  return { filed: true, sent, queued, noAddress, off: !enabled };
}
function payStubEmailText(args) {
  const money = (n) => `$${n.toFixed(2)}`;
  return [
    "STONEMILES \u2014 confirmed pay stub copy",
    "",
    `${args.label} \u2014 ${args.payer}`,
    args.isForm ? `Date received: ${args.paidAtIso.slice(0, 10)}` : `Pay date: ${args.paidAtIso.slice(0, 10)}`,
    `Gross pay: ${money(args.gross)}`,
    ...args.perDiem > 0 && !args.isForm ? [`Per diem (non-taxable, paid separately): ${money(args.perDiem)} \u2014 never part of filing gross.`] : [],
    ...args.sha256 ? [`Stub fingerprint (SHA-256): ${args.sha256}`] : [],
    args.hasAttachment ? "The stub file is attached to this email." : "The sealed stub itself is filed in the driver's STONEMILES Pay Book and in the stub's record.",
    "",
    "This copy was emailed because the driver confirmed this stub into their Pay Book and has pay-stub email copies turned on in Document copies settings. W-2 and 1099 pay file separately \u2014 this email carries this one stub only and is never merged into a filing figure."
  ].join(`
`);
}
