async function returnVestingTranche(ctx, v, opts) {
  const db = ctx.db();
  const claimed = await db.update(welcomeVesting3).set({ status: "returned", note: opts.note }).where(and(eq(welcomeVesting3.id, v.id), eq(welcomeVesting3.status, "pending"))).returning({ id: welcomeVesting3.id });
  if (!claimed[0])
    return false;
  try {
    await db.insert(earningPoolLedger3).values({
      kind: "welcome_vesting_returned",
      amountStoner: 0,
      username: v.username,
      refKey: `welcome_vesting_returned:${v.id}`,
      note: welcomeVestingReturnedNote(v)
    });
  } catch {}
  await appendChain(ctx, {
    refKind: "driver",
    refId: null,
    sessionId: null,
    event: "welcome_vesting_returned",
    payload: {
      username: v.username,
      plan: v.plan,
      tranche: `${v.trancheNo}/${v.totalTranches}`,
      amountUsd: v.amountUsd,
      amountStoner: v.amountStoner,
      reason: opts.reason,
      at: new Date().toISOString()
    }
  });
  return true;
}
async function settleRetainerIfExpired(ctx, username) {
  const db = ctx.db();
  const r = await latestRetainer(ctx, username);
  if (!r || r.status !== "active" || Date.now() < r.endsAt.getTime())
    return;
  const claimed = await db.update(accountRetainers3).set({ status: "expired", expiredAt: new Date, updatedAt: new Date }).where(and(eq(accountRetainers3.id, r.id), eq(accountRetainers3.status, "active"))).returning({ id: accountRetainers3.id });
  if (!claimed[0])
    return;
  const pending = await db.select().from(welcomeVesting3).where(and(eq(welcomeVesting3.username, username), eq(welcomeVesting3.status, "pending")));
  let returned = 0;
  for (const v of pending) {
    const note = v.amountUsd != null ? `vesting stopped \u2014 the 2-week retainer ended without renewal; ${usdText(v.amountUsd)} of credit value returned to the driver earning pool` : `vesting stopped \u2014 the 2-week retainer ended without renewal; ${v.amountStoner} $STONER returned to the driver earning pool`;
    if (await returnVestingTranche(ctx, v, { note, reason: "retainer_expired" }))
      returned++;
  }
  await appendChain(ctx, {
    refKind: "driver",
    refId: null,
    sessionId: null,
    event: "points_retainer_expired",
    payload: {
      username,
      plan: r.plan,
      startedAt: r.startedAt.toISOString(),
      endsAt: r.endsAt.toISOString(),
      tranchesReturned: returned,
      earnedPoints: "retained_in_full_locked",
      at: new Date().toISOString()
    }
  });
}
async function settleHoldIfEnded(ctx, username) {
  const db = ctx.db();
  const h = await latestHold(ctx, username);
  if (!h || h.status !== "active" || Date.now() < h.endsAt.getTime())
    return;
  if (!isGoldPlan(await myPlan(ctx)))
    return;
  const claimed = await db.update(accountHolds3).set({ status: "completed", updatedAt: new Date }).where(and(eq(accountHolds3.id, h.id), eq(accountHolds3.status, "active"))).returning({ id: accountHolds3.id });
  if (!claimed[0])
    return;
  await appendChain(ctx, {
    refKind: "driver",
    refId: null,
    sessionId: null,
    event: "points_reactivation_hold_completed",
    payload: {
      username,
      branch: h.branch,
      startedAt: h.startedAt.toISOString(),
      endsAt: h.endsAt.toISOString(),
      at: new Date().toISOString()
    }
  });
}
async function settleAccountLifecycle(ctx, username) {
  await settleRetainerIfExpired(ctx, username);
  await settleHoldIfEnded(ctx, username);
}
async function startReactivationHold(ctx, username, retainerId, branch, now) {
  const db = ctx.db();
  const existing = await latestHold(ctx, username);
  if (existing && existing.status === "active")
    return;
  const ends = new Date(holdEndsAt(now.getTime()));
  await db.insert(accountHolds3).values({
    username,
    retainerId,
    branch,
    startedAt: now,
    endsAt: ends,
    status: "active"
  });
  await appendChain(ctx, {
    refKind: "driver",
    refId: null,
    sessionId: null,
    event: "points_reactivation_hold_started",
    payload: {
      username,
      branch,
      retainerId,
      startedAt: now.toISOString(),
      endsAt: ends.toISOString(),
      at: now.toISOString()
    }
  });
}
async function notePlanTransition(ctx, username, prevPlan, newPlan) {
  const db = ctx.db();
  const prevPaid = isGoldPlan(prevPlan);
  const newPaid = isGoldPlan(newPlan);
  const now = new Date;
  if (newPaid) {
    await settleRetainerIfExpired(ctx, username);
    const r = await latestRetainer(ctx, username);
    if (r && r.status === "active") {
      const shift = vestingShiftOnLift(r.startedAt.getTime(), now.getTime());
      await db.update(accountRetainers3).set({ status: "lifted", liftedAt: now, updatedAt: now }).where(eq(accountRetainers3.id, r.id));
      if (shift > 0) {
        const pending = await db.select().from(welcomeVesting3).where(and(eq(welcomeVesting3.username, username), eq(welcomeVesting3.status, "pending")));
        for (const v of pending) {
          await db.update(welcomeVesting3).set({ dueAt: new Date(v.dueAt.getTime() + shift) }).where(eq(welcomeVesting3.id, v.id));
        }
      }
      await appendChain(ctx, {
        refKind: "driver",
        refId: null,
        sessionId: null,
        event: "points_retainer_lifted",
        payload: {
          username,
          plan: r.plan,
          startedAt: r.startedAt.toISOString(),
          liftedAt: now.toISOString(),
          vestingShiftMs: shift,
          at: now.toISOString()
        }
      });
      await startReactivationHold(ctx, username, r.id, "renewed_in_retainer", now);
    } else if (r && r.status === "expired") {
      await startReactivationHold(ctx, username, r.id, "returned_after_expiry", now);
    }
    return;
  }
  if (!prevPaid)
    return;
  const h = await latestHold(ctx, username);
  let cancelledHold = false;
  if (h && h.status === "active") {
    await db.update(accountHolds3).set({ status: "cancelled", cancelledAt: now, updatedAt: now }).where(eq(accountHolds3.id, h.id));
    cancelledHold = true;
    await appendChain(ctx, {
      refKind: "driver",
      refId: null,
      sessionId: null,
      event: "points_reactivation_hold_cancelled",
      payload: {
        username,
        branch: h.branch,
        startedAt: h.startedAt.toISOString(),
        cancelledAt: now.toISOString(),
        at: now.toISOString()
      }
    });
  }
  const existing = await latestRetainer(ctx, username);
  if (existing && existing.status === "active")
    return;
  const ends = new Date(retainerEndsAt(now.getTime()));
  await db.insert(accountRetainers3).values({
    username,
    plan: normalizePlan(prevPlan),
    startedAt: now,
    endsAt: ends,
    status: "active"
  });
  await appendChain(ctx, {
    refKind: "driver",
    refId: null,
    sessionId: null,
    event: "points_retainer_started",
    payload: {
      username,
      plan: normalizePlan(prevPlan),
      startedAt: now.toISOString(),
      endsAt: ends.toISOString(),
      cancelledHold,
      at: now.toISOString()
    }
  });
}
var DRIVER_TZ = "America/Chicago";
function localDayKey(d) {
  return new Intl.DateTimeFormat("en-CA", {
    timeZone: DRIVER_TZ,
    year: "numeric",
    month: "2-digit",
    day: "2-digit"
  }).format(d);
}
function localDayStartMs(d) {
  const key = localDayKey(d);
  const [y = 1970, m = 1, dd = 1] = key.split("-").map(Number);
  const probe = Date.UTC(y, m - 1, dd, 12, 0, 0);
  for (let deltaH = -14;deltaH <= 14; deltaH++) {
    const cand = probe + deltaH * 3600000;
    if (localDayKey(new Date(cand)) === key && localDayKey(new Date(cand - 1)) !== key) {
      return cand;
    }
  }
  return probe - 5 * 3600000;
}
