async function awardDailyTask(ctx, args) {
  const def = DAILY_TASKS.find((t) => t.key === args.task);
  if (!def)
    return 0;
  const points = dailyTaskPoints(args.task, await dailyPointsPaidTier(ctx));
  if (points <= 0)
    return 0;
  const dayKey = args.dayKey ?? localDayKey(new Date);
  const db = ctx.db();
  const rows = await db.select().from(pointsLog3).where(eq(pointsLog3.username, args.username));
  const isDaily = (r) => r.refKey != null && r.refKey.startsWith("daily:") && r.refKey.includes(`:${dayKey}`) || r.amount < 0 && r.source.startsWith("daily_") && localDayKey(r.createdAt) === dayKey;
  const netForTask = rows.filter((r) => isDaily(r) && r.source === `daily_${args.task}`).reduce((s, r) => s + r.amount, 0);
  if (netForTask > 0)
    return 0;
  const dayTotal = rows.filter(isDaily).reduce((s, r) => s + r.amount, 0);
  if (dayTotal + points > DAILY_POINTS_CAP)
    return 0;
  for (const suffix of ["", "-x2", "-x3"]) {
    const awarded = await awardPoints(ctx, {
      username: args.username,
      amount: points,
      reason: args.reason,
      source: `daily_${args.task}`,
      refKey: `daily:${args.task}:${dayKey}${args.refSuffix ?? ""}${suffix}`,
      createdAt: args.at
    });
    if (awarded)
      return points;
  }
  return 0;
}
