function mintCodeString(prefix, groups, alphabet) {
  let out = prefix;
  groups.forEach((len, gi) => {
    if (gi > 0)
      out += "-";
    for (let i = 0;i < len; i++) {
      out += alphabet[Math.floor(Math.random() * alphabet.length)];
    }
  });
  return out;
}
