async function accountShellFor(ctx, username) {
  const db = ctx.db();
  const me = await myUsername(ctx);
  const isLocal = username === me;
  const social = (await db.select().from(socialUsers3).where(eq(socialUsers3.username, username)).limit(1))[0];
  const overlay = (await db.select().from(accountAdmin3).where(eq(accountAdmin3.username, username)).limit(1))[0];
  const seat = (await db.select().from(teamSeats3).where(eq(teamSeats3.username, username)).limit(1))[0];
  const lock = (await db.select().from(accountLocks3).where(eq(accountLocks3.username, username)).limit(1))[0];
  const members = await db.select().from(companyMembers3).where(eq(companyMembers3.username, username));
  const member = members[0];
  let companyName = social?.company ?? null;
  if (member) {
    const comp = (await db.select().from(companies3).where(eq(companies3.id, member.companyId)).limit(1))[0];
    if (comp)
      companyName = comp.name;
  }
  let email = null;
  const docSettings = (await db.select({ driverEmail: docCopySettings3.driverEmail }).from(docCopySettings3).where(eq(docCopySettings3.username, username)).limit(1))[0];
  if (docSettings?.driverEmail)
    email = docSettings.driverEmail;
  if (!email) {
    const shipper = (await db.select({ email: shipperAccounts3.email }).from(shipperAccounts3).where(eq(shipperAccounts3.linkedUsername, username)).limit(1))[0];
    if (shipper?.email)
      email = shipper.email;
  }
  if (!email) {
    const broker = (await db.select({ email: brokerAccounts3.email }).from(brokerAccounts3).where(eq(brokerAccounts3.linkedUsername, username)).limit(1))[0];
    if (broker?.email)
      email = broker.email;
  }
  let tier = overlay?.tier ?? null;
  let trucks = overlay?.trucks ?? null;
  let dispatchSeats = overlay?.dispatchSeats ?? null;
  if (isLocal) {
    const prof = (await db.select().from(profile3).where(eq(profile3.id, myProfileId(ctx))).limit(1))[0];
    if (prof) {
      if (!tier)
        tier = normalizePlan(prof.plan);
      if (trucks === null)
        trucks = prof.ownerTrucks;
      if (dispatchSeats === null)
        dispatchSeats = prof.ownerSeats;
    }
  } else if (!tier) {
    const subs = await db.select().from(subscriptionEvents3).where(eq(subscriptionEvents3.username, username)).orderBy(desc(subscriptionEvents3.id));
    const latest = subs.find((s) => !s.reversed);
    tier = latest ? normalizePlan(latest.plan) : "basic";
  }
  if (!tier)
    tier = "basic";
  let accountType = "driver";
  if (member) {
    accountType = member.role === "owner" ? "company owner" : member.role;
  } else if (isLocal) {
    const access = await betaAccessRow(ctx);
    if (access?.accountKind === "owner")
      accountType = "owner";
  }
  if (seat?.active)
    accountType = "team";
  let betaAccess = overlay?.betaAccess ?? null;
  if (betaAccess === null) {
    if (isLocal) {
      const access = await betaAccessRow(ctx);
      betaAccess = access ? access.unlocked : null;
    } else {
      const codes = await db.select({ id: betaCodes3.id }).from(betaCodes3).where(eq(betaCodes3.usedBy, username)).limit(1);
      betaAccess = codes.length > 0 ? true : null;
    }
  }
  let signupAt = social?.createdAt ?? null;
  if (!signupAt) {
    const codes = await db.select().from(betaCodes3).where(eq(betaCodes3.usedBy, username)).orderBy(asc(betaCodes3.id));
    signupAt = codes[0]?.usedAt ?? null;
  }
  if (!signupAt && isLocal) {
    const access = await betaAccessRow(ctx);
    signupAt = access?.unlockedAt ?? null;
  }
  return buildAccountShell({
    username,
    displayName: social?.displayName ?? (isLocal ? (await db.select({ chatName: profile3.chatName }).from(profile3).where(eq(profile3.id, myProfileId(ctx))).limit(1))[0]?.chatName ?? null : null),
    email,
    accountType,
    tier,
    companyName,
    trucks,
    dispatchSeats,
    adminSuspended: overlay?.status === "suspended",
    locked: (lock?.locked ?? false) || (member?.loginDisabled ?? false),
    betaAccess,
    signupAt
  });
}
