async function myReferralCode(ctx, username) {
  const db = ctx.db();
  const rows = await db.select().from(referralCodes3).where(eq(referralCodes3.username, username)).limit(1);
  if (rows[0])
    return rows[0].code;
  for (let attempt = 0;attempt < 10; attempt++) {
    const code = mintCodeString("MILE-REF-", [6], CODE_ALPHABET);
    const clash = await db.select().from(referralCodes3).where(eq(referralCodes3.code, code));
    if (clash.length === 0) {
      await db.insert(referralCodes3).values({ username, code });
      return code;
    }
  }
  throw new Error("myReferralCode: could not mint a unique code");
}
