async function linkReferral(ctx, me, rawCode) {
  const db = ctx.db();
  const code = rawCode.trim().toUpperCase();
  if (!code)
    return "Enter a referral code first.";
  const owners = await db.select().from(referralCodes3).where(eq(referralCodes3.code, code));
  const owner = owners[0];
  if (!owner)
    return "That referral code isn't recognized \u2014 check it and try again.";
  if (owner.username.toLowerCase() === me.toLowerCase())
    return "That's your own referral code \u2014 self-referrals don't count.";
  const existing = await db.select().from(referralLinks3).where(eq(referralLinks3.referredUsername, me));
  if (existing.length > 0)
    return `You're already linked to @${existing[0].referrerUsername} \u2014 a referral link is set once, at signup.`;
  await db.insert(referralLinks3).values({
    referrerUsername: owner.username,
    referredUsername: me
  });
  await appendChain(ctx, {
    refKind: "driver",
    refId: null,
    sessionId: null,
    event: "referral_linked",
    payload: {
      referrer: owner.username,
      referred: me,
      reason: "referral",
      at: new Date().toISOString()
    }
  });
  return null;
}
async function processReferralQueue(ctx) {
  return enqueuePayout(async () => {
    const db = ctx.db();
    await repairClaimedPayouts(ctx);
    const queued = await db.select().from(referralRewards3).where(eq(referralRewards3.status, "queued")).orderBy(asc(referralRewards3.id));
    let balance = await rewardWalletBalance(ctx);
    for (const r of queued) {
      if (balance < r.amountStoner)
        continue;
      const claimed = await db.update(referralRewards3).set({ status: "paid", paidAt: new Date }).where(and(eq(referralRewards3.id, r.id), eq(referralRewards3.status, "queued"))).returning({ id: referralRewards3.id });
      if (!claimed[0])
        continue;
      try {
        await db.insert(rewardWalletLedger3).values({
          kind: "referral_payout",
          amountStoner: -r.amountStoner,
          username: r.referrerUsername,
          refKey: `referral_reward:${r.id}`,
          note: `Referral reward \u2014 @${r.referredUsername}'s first paid subscription`
        });
      } catch {}
      await appendChain(ctx, {
        refKind: "driver",
        refId: null,
        sessionId: null,
        event: "referral_reward_paid",
        payload: {
          referrer: r.referrerUsername,
          referred: r.referredUsername,
          amountStoner: r.amountStoner,
          reason: "referral",
          at: new Date().toISOString()
        }
      });
      balance -= r.amountStoner;
    }
  });
}
async function processWelcomeVesting(ctx, opts) {
  if (await payoutRunBlock(ctx, opts) != null)
    return { paid: 0, returned: 0 };
  return enqueuePayout(async () => {
    const db = ctx.db();
    await repairClaimedPayouts(ctx);
    const vestMe = await myUsername(ctx);
    await settleRetainerIfExpired(ctx, vestMe);
    if (vestingClockAction(await myStanding(ctx)) === "pause")
      return { paid: 0, returned: 0 };
    const now = Date.now();
    const due = (await db.select().from(welcomeVesting3).where(eq(welcomeVesting3.status, "pending")).orderBy(asc(welcomeVesting3.dueAt), asc(welcomeVesting3.id))).filter((v) => v.dueAt.getTime() <= now);
    const priceUsd = await liveStonerPriceUsd(ctx);
    let paid = 0;
    let returned = 0;
    let balance = await earningPoolBalance(ctx);
    for (const v of due) {
      const credit = (await db.select().from(welcomeCredits3).where(eq(welcomeCredits3.id, v.welcomeCreditId)).limit(1))[0];
      if (!credit || credit.status !== "paid")
        continue;
      const currentPlan = await myPlan(ctx);
      if (!welcomeVestingActive(currentPlan, v.plan)) {
        const note = v.amountUsd != null ? `vesting stopped \u2014 subscription ended; ${usdText(v.amountUsd)} of credit value returned to the driver earning pool` : `vesting stopped \u2014 subscription ended; ${v.amountStoner} $STONER returned to the driver earning pool`;
        if (await returnVestingTranche(ctx, v, { note, reason: "subscription_ended" }))
          returned++;
        continue;
      }
      let tokens;
      if (v.amountUsd != null) {
        const t = tokensForUsd(v.amountUsd, priceUsd);
        if (t == null)
          continue;
        tokens = t;
      } else {
        tokens = v.amountStoner;
      }
      if (balance < tokens)
        continue;
      const claimed = await db.update(welcomeVesting3).set({ status: "paid", paidAt: new Date, amountStoner: tokens }).where(and(eq(welcomeVesting3.id, v.id), eq(welcomeVesting3.status, "pending"))).returning({ id: welcomeVesting3.id });
      if (!claimed[0])
        continue;
      try {
        await db.insert(earningPoolLedger3).values({
          kind: "welcome_vesting_payout",
          amountStoner: -tokens,
          username: v.username,
          refKey: `welcome_vesting:${v.id}`,
          note: welcomeVestingLedgerNote(v)
        });
      } catch {}
      if (v.amountUsd != null) {
        await recordBackingSpendIfLive(ctx, {
          amountUsd: v.amountUsd,
          username: v.username,
          refKey: `backing_spend:welcome_vesting:${v.id}`,
          note: `Welcome vesting tranche #${v.id} \u2014 USDG backing spent at payout`
        });
      }
      await appendChain(ctx, {
        refKind: "driver",
        refId: null,
        sessionId: null,
        event: "welcome_vesting_paid",
        payload: {
          username: v.username,
          plan: v.plan,
          tranche: `${v.trancheNo}/${v.totalTranches}`,
          amountUsd: v.amountUsd,
          priceUsd: v.amountUsd != null ? priceUsd : null,
          amountStoner: tokens,
          source: "earning_pool",
          at: new Date().toISOString()
        }
      });
      balance -= tokens;
      paid++;
    }
    return { paid, returned };
  });
}
async function maybeAwardReferralReward(ctx, payerUsername) {
  const db = ctx.db();
  const links = await db.select().from(referralLinks3).where(eq(referralLinks3.referredUsername, payerUsername));
  const link = links[0];
  if (!link)
    return;
  if (link.referrerUsername.toLowerCase() === payerUsername.toLowerCase())
    return;
  const existing = await db.select().from(referralRewards3).where(eq(referralRewards3.referredUsername, payerUsername));
  if (existing.length > 0)
    return;
  const priorActive = await activeReferralCount(ctx, link.referrerUsername);
  const newActive = priorActive + 1;
  const level = referralLevelForCount(newActive);
  const rate = level.rate;
  const amount = await referralRewardAmount(ctx);
  await db.insert(referralRewards3).values({
    referrerUsername: link.referrerUsername,
    referredUsername: payerUsername,
    amountStoner: amount,
    status: "queued"
  });
  await appendChain(ctx, {
    refKind: "driver",
    refId: null,
    sessionId: null,
    event: "referral_reward_queued",
    payload: {
      referrer: link.referrerUsername,
      referred: payerUsername,
      amountStoner: amount,
      reason: "referral",
      referralLevel: level.key,
      referralPoints: rate,
      activeReferrals: newActive,
      at: new Date().toISOString()
    }
  });
  await awardPoints(ctx, {
    username: link.referrerUsername,
    amount: rate,
    reason: `Referral \u2014 @${payerUsername}'s first paid subscription settled: +${rate} SM Points for referring @${payerUsername} (settled first subscription, ${level.name} rate \u2014 ${newActive} active referral${newActive === 1 ? "" : "s"})`,
    source: "referral",
    refKey: `referral-points:${payerUsername}`
  });
  for (const lvl of REFERRAL_LEVELS) {
    if (lvl.milestoneThreshold == null || lvl.milestonePoints <= 0)
      continue;
    if (!(priorActive < lvl.milestoneThreshold && newActive >= lvl.milestoneThreshold))
      continue;
    const stateRows = await db.select().from(referralMilestones3).where(and(eq(referralMilestones3.referrerUsername, link.referrerUsername), eq(referralMilestones3.levelKey, lvl.key))).limit(1);
    let state = stateRows[0];
    if (!state) {
      const inserted = await db.insert(referralMilestones3).values({
        referrerUsername: link.referrerUsername,
        levelKey: lvl.key,
        threshold: lvl.milestoneThreshold,
        bonusPoints: lvl.milestonePoints,
        paid: false,
        reversed: false
      }).returning({ id: referralMilestones3.id });
      const fresh = await db.select().from(referralMilestones3).where(eq(referralMilestones3.id, inserted[0].id)).limit(1);
      state = fresh[0];
    }
    if (!state || state.paid)
      continue;
    const awarded = await awardPoints(ctx, {
      username: link.referrerUsername,
      amount: lvl.milestonePoints,
      reason: `Referral milestone \u2014 ${lvl.name}: +${lvl.milestonePoints.toLocaleString("en-US")} SM Points for reaching ${lvl.milestoneThreshold} active referrals (one-time level milestone)`,
      source: "referral_milestone",
      refKey: `referral-milestone:${link.referrerUsername}:${lvl.key}`
    });
    await db.update(referralMilestones3).set({ paid: true, paidAt: new Date, updatedAt: new Date }).where(eq(referralMilestones3.id, state.id));
    await appendChain(ctx, {
      refKind: "driver",
      refId: null,
      sessionId: null,
      event: "referral_milestone_paid",
      payload: {
        referrer: link.referrerUsername,
        level: lvl.key,
        levelName: lvl.name,
        threshold: lvl.milestoneThreshold,
        points: lvl.milestonePoints,
        activeReferrals: newActive,
        reason: "referral_milestone",
        at: new Date().toISOString()
      }
    });
  }
  await processReferralQueue(ctx);
}
