var SIGNUP_POINTS = 100;
var SUBSCRIPTION_POINTS = 1000;
var REFERRAL_POINTS = 250;
var REFERRAL_LEVELS = [
  { key: "spotter", name: "Spotter", rangeLabel: "1\u20134 active", minActive: 0, rate: 250, milestoneThreshold: null, milestonePoints: 0 },
  { key: "dispatcher", name: "Dispatcher", rangeLabel: "5+ active", minActive: 5, rate: 350, milestoneThreshold: 5, milestonePoints: 1000 },
  { key: "fleet_builder", name: "Fleet Builder", rangeLabel: "15+ active", minActive: 15, rate: 500, milestoneThreshold: 15, milestonePoints: 2500 },
  { key: "road_captain", name: "Road Captain", rangeLabel: "40+ active", minActive: 40, rate: 750, milestoneThreshold: 40, milestonePoints: 5000 }
];
function referralLevelForCount(activeCount) {
  let level = REFERRAL_LEVELS[0];
  for (const l of REFERRAL_LEVELS)
    if (activeCount >= l.minActive)
      level = l;
  return level;
}
function nextReferralLevel(activeCount) {
  for (const l of REFERRAL_LEVELS)
    if (activeCount < l.minActive)
      return l;
  return null;
}
async function activeReferralCount(ctx, referrerUsername) {
  const db = ctx.db();
  const rewards = await db.select().from(referralRewards3).where(eq(referralRewards3.referrerUsername, referrerUsername));
  if (rewards.length === 0)
    return 0;
  const myPoints = await db.select().from(pointsLog3).where(eq(pointsLog3.username, referrerUsername));
  const clawedReferred = new Set;
  for (const row of myPoints) {
    if (row.refKey?.startsWith("clawback-referral-points:")) {
      clawedReferred.add(row.refKey.slice("clawback-referral-points:".length).toLowerCase());
    }
  }
  return rewards.filter((r) => !clawedReferred.has(r.referredUsername.toLowerCase())).length;
}
async function referralLevelSummary(ctx, username) {
  const activeCount = await activeReferralCount(ctx, username);
  const level = referralLevelForCount(activeCount);
  const nextLevel = nextReferralLevel(activeCount);
  return {
    activeCount,
    level,
    nextLevel,
    toNextLevel: nextLevel ? nextLevel.minActive - activeCount : null,
    isRoadCaptain: level.key === "road_captain"
  };
}
async function roadCaptainReferrers(ctx) {
  const db = ctx.db();
  const rewards = await db.select().from(referralRewards3);
  const referrers = [...new Set(rewards.map((r) => r.referrerUsername))];
  const out = [];
  for (const referrer of referrers) {
    const activeCount = await activeReferralCount(ctx, referrer);
    if (activeCount >= 40)
      out.push({ username: referrer, activeCount });
  }
  return out.sort((a, b) => b.activeCount - a.activeCount);
}
