        payload: {
          loadId: load.id,
          invoiceId: existing.id,
          packetRef: packet.packetRef,
          previousFreightAmount: plan.action === "update_amount" ? plan.previousFreightAmount : existing.freightAmount,
          previousFeeAmount: plan.action === "update_amount" ? plan.previousFeeAmount : existing.feeAmount,
          freightAmount: freight,
          feeAmount: plan.feeAmount,
          note: "The packet's final freight amount was corrected \u2014 the dispatch fee follows the final amount on the same invoice (one fee per load, ever).",
          at: new Date().toISOString()
        }
