function gateRefusalMessage(gate) {
  const b = gate.blocking;
  if (!b)
    return "Dispatch fee outstanding \u2014 pay to keep picking loads.";
  if (gate.revoked) {
    return `Board permission revoked \u2014 dispatch fee outstanding on load #${b.loadId} ($${b.balanceDue.toFixed(2)} of $${b.feeAmount.toFixed(2)}, ${b.daysOutstanding} days past delivery). Settle the fee in full (ACH, debit, or crypto) to restore board access.`;
  }
  return `Dispatch fee outstanding on load #${b.loadId} \u2014 $${b.balanceDue.toFixed(2)} due (10% dispatch fee, ${b.daysOutstanding} day${b.daysOutstanding === 1 ? "" : "s"} since delivery). Pay to keep picking loads \u2014 ACH, debit, or crypto.`;
}
async function verifyCryptoTx(txHash, chain) {
  const rpc = chain === "robinhood" ? "https://rpc.mainnet.chain.robinhood.com" : "https://mainnet.base.org";
  const chainId = chain === "robinhood" ? 4663 : 8453;
  if (!/^0x[0-9a-fA-F]{64}$/.test(txHash.trim())) {
    return { outcome: "unavailable", detail: "The reference is not a transaction-hash shape, so on-chain verification could not run." };
  }
  try {
    const res = await fetch(rpc, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ jsonrpc: "2.0", id: 1, method: "eth_getTransactionByHash", params: [txHash.trim()] })
    });
    if (!res.ok)
      return { outcome: "unavailable", detail: `Chain ${chainId} RPC answered HTTP ${res.status} \u2014 verification could not run.` };
    const body = await res.json();
    const tx = body.result;
    if (!tx)
      return { outcome: "not_found", detail: `No transaction with this hash exists on chain ${chainId}.` };
    const expected = (DISPATCH_FEE_CRYPTO_ADDRESS ?? "").toLowerCase();
    if (chain === "robinhood" && expected && (tx.to ?? "").toLowerCase() !== expected) {
      return {
        outcome: "recipient_mismatch",
        detail: `The transaction exists on Robinhood Chain (4663) but its recipient is not the STONEMILES house lane (dispatch-fee address) \u2014 recorded as admin-confirmed with this flag on it.`
      };
    }
    return { outcome: "verified", detail: `Transaction found on chain ${chainId}${chain === "robinhood" ? " paying the STONEMILES house lane (dispatch-fee address)" : ""}.` };
  } catch {
    return { outcome: "unavailable", detail: `Chain ${chainId} RPC unreachable \u2014 verification could not run.` };
  }
}
var GIVEAWAY_TOKEN_CONTRACTS = {
  USDG: { address: USDG_CONTRACT_ADDRESS, decimals: 6 },
  STONER: { address: null, decimals: 18 },
  ETH: { address: null, decimals: 18 }
};
var ERC20_TRANSFER_TOPIC = "0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef";
async function verifyGiveawayTx(txHash, currency, expectedAddress) {
  const rpc = "https://rpc.mainnet.chain.robinhood.com";
  const hash = txHash.trim();
  if (!/^0x[0-9a-fA-F]{64}$/.test(hash)) {
    return {
      outcome: "unavailable",
      verifiedAmount: null,
      detail: "The reference is not a transaction-hash shape, so on-chain verification could not run."
    };
  }
  const token = GIVEAWAY_TOKEN_CONTRACTS[currency];
  if (currency !== "ETH" && token.address == null) {
    return {
      outcome: "unavailable",
      verifiedAmount: null,
      detail: `${currency} has no verified token contract address in the app yet, so this transfer cannot be confirmed from the transaction \u2014 recorded honestly as not verified.`
    };
  }
  const call = async (method, params) => {
    const res = await fetch(rpc, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ jsonrpc: "2.0", id: 1, method, params })
    });
    if (!res.ok)
      throw new Error(`RPC HTTP ${res.status}`);
    const body = await res.json();
    return body.result ?? null;
  };
  try {
    const tx = await call("eth_getTransactionByHash", [hash]);
    if (!tx) {
      return {
        outcome: "not_found",
        verifiedAmount: null,
        detail: "No transaction with this hash exists on Robinhood Chain (4663)."
      };
    }
    const expected = expectedAddress.toLowerCase();
    if (currency === "ETH") {
      if ((tx.to ?? "").toLowerCase() !== expected) {
        return {
          outcome: "recipient_mismatch",
          verifiedAmount: null,
          detail: `The transaction exists on Robinhood Chain (4663) but it does not pay ${expectedAddress}.`
        };
      }
      let amount = 0;
      try {
        amount = Number(BigInt(tx.value ?? "0x0")) / 1000000000000000000;
      } catch {
        amount = 0;
      }
      return {
        outcome: "verified",
        verifiedAmount: amount,
        detail: `Native ETH transfer to ${expectedAddress} confirmed on Robinhood Chain (4663): ${amount} ETH.`
      };
    }
    const receipt = await call("eth_getTransactionReceipt", [hash]);
    if (!receipt || !Array.isArray(receipt.logs)) {
      return {
        outcome: "unavailable",
        verifiedAmount: null,
        detail: "The transaction exists but its receipt could not be read yet \u2014 verification could not complete."
      };
    }
    const contract = (token.address ?? "").toLowerCase();
    const toTopic = `0x${"0".repeat(24)}${expected.replace(/^0x/, "")}`;
    let totalRaw = 0n;
    let sawTokenTransfer = false;
    let sawAnyToExpected = false;
    for (const log of receipt.logs) {
      if ((log.address ?? "").toLowerCase() !== contract)
        continue;
      if ((log.topics?.[0] ?? "").toLowerCase() !== ERC20_TRANSFER_TOPIC)
        continue;
      sawTokenTransfer = true;
      if ((log.topics?.[2] ?? "").toLowerCase() === toTopic) {
        sawAnyToExpected = true;
        try {
          totalRaw += BigInt(log.data ?? "0x0");
        } catch {}
      }
    }
    if (sawAnyToExpected) {
      const amount = Number(totalRaw) / 10 ** token.decimals;
      return {
        outcome: "verified",
        verifiedAmount: amount,
        detail: `${currency} transfer to ${expectedAddress} confirmed on Robinhood Chain (4663): ${amount} ${currency}.`
      };
    }
    if (sawTokenTransfer) {
      return {
        outcome: "recipient_mismatch",
        verifiedAmount: null,
        detail: `The transaction moves ${currency} on Robinhood Chain (4663), but not to ${expectedAddress}.`
      };
    }
    return {
      outcome: "recipient_mismatch",
      verifiedAmount: null,
      detail: `The transaction exists on Robinhood Chain (4663) but contains no ${currency} transfer \u2014 nothing in it pays ${expectedAddress} in ${currency}.`
    };
  } catch {
    return {
      outcome: "unavailable",
      verifiedAmount: null,
      detail: "Robinhood Chain (4663) RPC unreachable \u2014 verification could not run."
    };
  }
}
