async function reevaluateSealGradeForLoad(ctx, load, basis) {
  const db = ctx.db();
  const pods = await podStatusByLoad(ctx);
  const pod = pods.get(load.id);
  if (!pod?.sealed)
    return;
  const chain = await db.select().from(chainLog3).where(eq(chainLog3.refId, load.id)).orderBy(asc(chainLog3.id));
  let distanceMi = null;
  for (const r of chain) {
    if (r.refKind !== "load")
      continue;
    if (r.event === "pod_seal") {
      try {
        distanceMi = JSON.parse(r.payload).geofenceMiles ?? null;
      } catch {
        distanceMi = null;
      }
    } else if (r.event === "pod_seal_void") {
      distanceMi = null;
    }
  }
  const result = await sealGradeForLoad(ctx, load, distanceMi);
  const changed = result.grade !== pod.grade || JSON.stringify(result.criteria) !== JSON.stringify(pod.gradeCriteria);
  if (!changed)
    return;
  await appendChain(ctx, {
    refKind: "load",
    refId: load.id,
    sessionId: null,
    event: "pod_seal_grade",
    payload: {
      loadId: load.id,
      sealGrade: result.grade,
      gradeCriteria: result.criteria,
      basis,
      tripQueueId: load.tripQueueId ?? null,
      at: new Date().toISOString()
    }
  });
}
