async function createLoadFromBoard(ctx, board, driverUsername) {
  const db = ctx.db();
  const profRows = await db.select().from(profile3).where(eq(profile3.id, myProfileId(ctx))).limit(1);
  const prof = profRows[0];
  const fields = {
    shipper: board.shipper,
    pickupCity: board.pickupCity,
    pickupState: board.pickupState,
    deliveryCity: board.deliveryCity,
    deliveryState: board.deliveryState,
    pickupText: board.pickupText,
    deliveryText: board.deliveryText,
    rate: board.rate,
    weightLbs: board.weightLbs,
    commodity: board.commodity,
    hazmat: board.hazmat ?? false
  };
  const ins = await db.insert(loads3).values({
    ...fields,
    loadedMiles: board.loadedMiles ?? null,
    milesSource: board.milesSource ?? null,
    extraCharges: board.extraCharges ?? 0,
    extraChargesNote: board.extraChargesNote ?? null,
    docBlobKey: board.docBlobKey ?? null,
    docMime: board.docMime ?? null,
    docSha256: board.docSha256 ?? null,
    equipmentType: board.equipmentType ?? null,
    trailerNumber: prof?.currentTrailer ?? null,
    status: "booked",
    brokerName: board.brokerName ?? null,
    brokerCompany: board.brokerCompany ?? null,
    brokerMc: board.brokerMc ?? null,
    brokerSource: board.brokerSource ?? null,
    brokerLinkId: board.brokerLinkId ?? null
  }).returning({ id: loads3.id });
  const loadId = ins[0]?.id;
  if (loadId == null)
    throw new Error("createLoadFromBoard: load insert returned no rows");
  const claimSource = (board.boardScope ?? "fleet") === "open" ? "open_board" : "fleet_board";
  await appendChain(ctx, {
    refKind: "load",
    refId: loadId,
    sessionId: null,
    event: "load_saved",
    payload: { ...fields, extraCharges: board.extraCharges ?? 0, extraChargesNote: board.extraChargesNote ?? null, source: claimSource, boardLoadId: board.id, originKind: board.originKind ?? null, originLabel: board.originLabel ?? null, driver: driverUsername }
  });
  if (board.docSha256) {
    await appendChain(ctx, {
      refKind: "load",
      refId: loadId,
      sessionId: null,
      event: "doc_sealed",
      payload: { sha256: board.docSha256, mime: board.docMime, source: claimSource, boardLoadId: board.id }
    });
  }
  const lane = (city, state) => [city, state].filter(Boolean).join(", ");
  const tripName = `${lane(board.pickupCity, board.pickupState) || "Pickup"} \u2192 ${lane(board.deliveryCity, board.deliveryState) || "Delivery"}`.slice(0, 120);
  const payRate = prof?.driverCpm ?? 0.55;
  const payBasis = prof?.payBasis === "percent" ? "percent" : "cpm";
  const payPercent = payBasis === "percent" ? prof?.driverPayPct ?? null : null;
  const tq = await db.insert(tripQueue3).values({
    name: tripName,
    origin: lane(board.pickupCity, board.pickupState) || null,
    destination: lane(board.deliveryCity, board.deliveryState) || null,
    status: "planned",
    loadId,
    notes: board.notes ?? null,
    payRate,
    payBasis,
    payPercent,
    extraCharges: board.extraCharges ?? 0,
    extraChargesNote: board.extraChargesNote ?? null,
    stopsJson: "[]"
  }).returning({ id: tripQueue3.id });
  const tripQueueId = tq[0]?.id;
  if (tripQueueId == null)
    throw new Error("createLoadFromBoard: trip insert returned no rows");
  await db.update(loads3).set({ tripQueueId }).where(eq(loads3.id, loadId));
  await appendChain(ctx, {
    refKind: "trip",
    refId: null,
    sessionId: null,
    event: "trip_queue_created",
    payload: { queueId: tripQueueId, name: tripName, loadId, source: claimSource, boardLoadId: board.id, driver: driverUsername, at: new Date().toISOString() }
  });
  return { loadId, tripQueueId };
}
async function takeBoardLoad(ctx, board, driverUsername, method, actor) {
  const db = ctx.db();
  const now = new Date;
  const flipped = await db.update(boardLoads3).set({ status: "taken", claimMethod: method, claimedBy: driverUsername, claimedAt: now, updatedAt: now }).where(and(eq(boardLoads3.id, board.id), eq(boardLoads3.status, "open"))).returning({ id: boardLoads3.id });
  if (!flipped[0]) {
    const fresh = await db.select().from(boardLoads3).where(eq(boardLoads3.id, board.id)).limit(1);
    const by = fresh[0]?.claimedBy;
    return {
      ok: false,
      error: by ? `Already taken \u2014 @${by} got this load first. It's off the board; the open loads below are still up for grabs.` : "That load is no longer open \u2014 it may have been withdrawn or taken. Refresh the board and pick another.",
      loadId: null,
      tripQueueId: null
    };
  }
  try {
    const takenRow = { ...board, status: "taken", claimMethod: method, claimedBy: driverUsername, claimedAt: now };
    const { loadId, tripQueueId } = await createLoadFromBoard(ctx, takenRow, driverUsername);
    await db.update(boardLoads3).set({ loadId, tripQueueId, updatedAt: new Date }).where(eq(boardLoads3.id, board.id));
    await appendChain(ctx, {
      refKind: "load",
      refId: loadId,
      sessionId: null,
      event: method === "claim" ? "board_load_claimed" : "board_load_assigned",
      payload: {
        boardLoadId: board.id,
        companyId: board.companyId,
        driver: driverUsername,
        by: actor,
        method,
        loadId,
        tripQueueId,
        lane: `${board.pickupCity ?? "?"} \u2192 ${board.deliveryCity ?? "?"}`,
        at: new Date().toISOString()
      }
    });
    return { ok: true, error: null, loadId, tripQueueId };
  } catch {
    await db.update(boardLoads3).set({ status: "open", claimMethod: null, claimedBy: null, claimedAt: null, loadId: null, tripQueueId: null, updatedAt: new Date }).where(eq(boardLoads3.id, board.id));
    return { ok: false, error: "Claiming hit a snag creating the load \u2014 nothing was taken and the load is back on the board. Try again.", loadId: null, tripQueueId: null };
  }
}
