async function refreshFleetBillingBasis(ctx, companyId) {
  const db = ctx.db();
  const compRows = await db.select().from(companies3).where(eq(companies3.id, companyId)).limit(1);
  const company = compRows[0];
  if (!company)
    return;
  const chain = await db.select().from(chainLog3).where(or(eq(chainLog3.event, "fleet_creation_plan_transition"), eq(chainLog3.event, "fleet_billing_basis_update"), eq(chainLog3.event, "dispatch_fleet_plan_activation"))).orderBy(desc(chainLog3.id));
  let anchor = null;
  let priorUpdates = 0;
  for (const entry of chain) {
    let payload;
    try {
      payload = JSON.parse(entry.payload);
    } catch {
      continue;
    }
    if (payload.companyId !== companyId)
      continue;
    if (entry.event === "fleet_billing_basis_update")
      priorUpdates += 1;
    if (!anchor && payload.billingBasis && typeof payload.fromPlan === "string") {
      anchor = {
        fromPlan: payload.fromPlan,
        period: payload.period === "yearly" ? "yearly" : "monthly",
        billingBasis: payload.billingBasis
      };
    }
  }
  if (!anchor)
    return;
  const members = await db.select().from(companyMembers3).where(eq(companyMembers3.companyId, companyId));
  const seats = countFleetRosterSeats(members);
  const basis = fleetSwitchBillingBasis({
    fromPlan: anchor.fromPlan,
    period: anchor.period,
    driverSeats: seats.driverSeats,
    dispatchSeats: seats.dispatchSeats
  });
  if (!fleetBillingBasisChanged(anchor.billingBasis, basis))
    return;
  await db.insert(subscriptionEvents3).values({
    username: company.ownerUsername,
    plan: "owner",
    period: anchor.period,
    kind: "fleet_basis",
    paymentRef: `fleet-billing:${companyId}:${priorUpdates + 1}`,
    pointsAwarded: 0,
    discounted: false,
    countedForGiveaway: false
  });
  await appendChain(ctx, {
    refKind: "driver",
    refId: null,
    sessionId: null,
    event: "fleet_billing_basis_update",
    payload: {
      username: company.ownerUsername,
      companyId,
      companyName: company.name,
      fromPlan: basis.fromPlan,
      toPlan: basis.toPlan,
      period: basis.period,
      cause: "roster_change",
      billingBasis: basis,
      billingLine: fleetSwitchBillingLine(basis),
      note: "Fleet billing basis recomputed from the current roster \u2014 no charge taken; billing begins at app-store release.",
      at: new Date().toISOString()
    }
  });
}
