function derivedStepDone(track, stepId, f) {
  if (track === "driver") {
    switch (stepId) {
      case "account":
        return f.accountDone;
      case "company":
        return f.hasCompany;
      case "profile":
        return f.profileDone;
      case "eld":
        return f.eldConnected;
      case "academy":
        return f.academyCompletions > 0;
      default:
        return false;
    }
  }
  switch (stepId) {
    case "company_setup":
      return f.setupComplete;
    case "driver_codes":
      return f.codesCount > 0;
    case "eld_connect":
      return f.eldConnected;
    case "invite_drivers":
      return f.memberCount > 1;
    default:
      return false;
  }
}
