      status: "ready",
      reason: "Ready",
      detail: `${pCity}, ${pState} \u2192 ${dCity}, ${dState}${rate != null ? ` \xB7 $${rate}` : ""}${weight != null ? ` \xB7 ${weight.toLocaleString()} lbs` : ""}`
