var lastEiaAttemptAt = 0;
var EIA_ATTEMPT_MIN_MS = 60 * 60000;
async function loadEiaView(ctx, opts = {}) {
  const db = ctx.db();
  let rows = await db.select().from(eiaDieselSnapshots3).orderBy(desc(eiaDieselSnapshots3.weekOf)).limit(1);
  if (rows.length === 0) {
    await db.insert(eiaDieselSnapshots3).values({
      weekOf: EIA_SEED.weekOf,
      national: EIA_SEED.national,
      gulfCoast: EIA_SEED.gulfCoast,
      westCoast: EIA_SEED.westCoast,
      source: EIA_SEED.source,
      sourceUrl: EIA_SOURCE_URL,
      fetchedAt: EIA_SEED.fetchedAt
    }).onConflictDoNothing();
    rows = await db.select().from(eiaDieselSnapshots3).orderBy(desc(eiaDieselSnapshots3.weekOf)).limit(1);
  }
  let row = rows[0];
  let refreshed = false;
  let refreshError = null;
  const now = new Date;
  const due = opts.force === true || eiaRefreshDue(row.fetchedAt, now);
  const throttled = Date.now() - lastEiaAttemptAt < EIA_ATTEMPT_MIN_MS;
  if (due && (opts.force === true || !throttled)) {
    lastEiaAttemptAt = Date.now();
    try {
      const snap = await fetchEiaDieselSnapshot();
      if (snap.weekOf !== row.weekOf) {
        await db.insert(eiaDieselSnapshots3).values({
          weekOf: snap.weekOf,
          national: snap.national,
          gulfCoast: snap.gulfCoast,
          westCoast: snap.westCoast,
          source: EIA_SOURCE_NAME,
          sourceUrl: EIA_SOURCE_URL,
          fetchedAt: new Date
        }).onConflictDoNothing();
        refreshed = true;
      } else {
        await db.update(eiaDieselSnapshots3).set({ fetchedAt: new Date, source: EIA_SOURCE_NAME }).where(eq(eiaDieselSnapshots3.weekOf, snap.weekOf));
        refreshed = true;
      }
      const fresh = await db.select().from(eiaDieselSnapshots3).orderBy(desc(eiaDieselSnapshots3.weekOf)).limit(1);
      if (fresh[0])
        row = fresh[0];
    } catch (e) {
      refreshError = e instanceof Error ? e.message : "EIA refresh failed \u2014 keeping the last good week.";
    }
  }
  const ageDays = eiaWeekAgeDays(row.weekOf, now);
  const stale = eiaIsStale(row.weekOf, now);
  const note = stale ? `EIA weekly on-highway diesel averages \u2014 regional context only, never a station price. Your stop will vary. This is the last good week on file (${eiaWeekLabel(row.weekOf)}, ${ageDays} days old) \u2014 the weekly refresh hasn't landed a newer week yet.` : "EIA weekly on-highway diesel averages \u2014 regional context only, never a station price. Your stop will vary.";
  return {
    refreshed,
    refreshError,
    view: {
      weekOf: eiaWeekLabel(row.weekOf),
      weekDate: row.weekOf,
      national: row.national,
      gulfCoast: row.gulfCoast,
      westCoast: row.westCoast,
      note,
      source: row.source,
      sourceUrl: row.sourceUrl,
      fetchedAt: row.fetchedAt.toISOString(),
      stale,
      ageDays
    }
  };
}
