  runPayoutBatch: defineAction({
    description: "Run payout batch.",
    request: object({}),
    response: object({
      ok: boolean2(),
      blockedReason: string2().nullable(),
      vestingPaid: number2(),
      vestingReturned: number2(),
      backingLive: boolean2(),
      coverage: number2().nullable(),
      payoutsPaused: boolean2(),
      error: string2().nullable()
    }),
    async handler(ctx) {
      if (!await isBetaOwner(ctx))
        return {
          ok: false,
          blockedReason: null,
          vestingPaid: 0,
          vestingReturned: 0,
          backingLive: false,
          coverage: null,
          payoutsPaused: false,
          error: "Only the owner (admin) can run a payout batch."
        };
      const before = await poolBackingStatus(ctx);
      if (before.settings.backingLive && before.assessment.payoutsPaused) {
        return {
          ok: false,
          blockedReason: `backing_paused:${before.assessment.pauseReason ?? "unknown"}`,
          vestingPaid: 0,
          vestingReturned: 0,
          backingLive: true,
          coverage: before.assessment.coverage,
          payoutsPaused: true,
          error: "Payouts are paused by the backing rules (USDG price unknown, severe depeg, or coverage below 1.00) \u2014 the batch did not run and every row stays queued."
        };
      }
      await processEarningPoolQueues(ctx, { batchAuthorized: true });
      const vesting = await processWelcomeVesting(ctx, { batchAuthorized: true });
      const after = await poolBackingStatus(ctx);
      ctx.invalidateQueries();
      return {
        ok: true,
        blockedReason: null,
        vestingPaid: vesting.paid,
        vestingReturned: vesting.returned,
        backingLive: after.settings.backingLive,
        coverage: after.assessment.coverage,
        payoutsPaused: after.assessment.payoutsPaused,
        error: null
      };
    }
  }),
