  sweepEarningPoolBacking: defineAction({
    description: "Sweep earning pool backing.",
    request: object({
      amountUsdg: number2().positive().max(1e8),
      note: string2().max(200).optional()
    }),
    response: object({ ok: boolean2(), error: string2().nullable() }),
    async handler(ctx, args) {
      const db = ctx.db();
      if (!await isBetaOwner(ctx))
        return { ok: false, error: "Only the owner (admin) can sweep Earning Pool backing." };
      const { assessment } = await poolBackingStatus(ctx);
      const guard = sweepGuard({
        backingUsd: assessment.backingUsd,
        floorUsd: assessment.floorUsd,
        sweepUsd: args.amountUsdg
      });
      if (!guard.allowed)
        return { ok: false, error: guard.reason };
      await db.insert(earningPoolBackingLedger3).values({
        kind: "sweep_out_usdg",
        amountUsdg: -args.amountUsdg,
        note: args.note?.trim() || "Owner sweep of surplus above the 30-day payout floor"
      });
      await appendChain(ctx, {
        refKind: "driver",
        refId: null,
        sessionId: null,
        event: "earning_pool_backing_swept",
        payload: {
          amountUsdg: args.amountUsdg,
          floorUsd: assessment.floorUsd,
          backingAfterUsd: guard.backingAfterUsd,
          at: new Date().toISOString()
        }
      });
      ctx.invalidateQueries();
      return { ok: true, error: null };
    }
  }),
