  getWelcomeCredit: defineAction({
    description: "Get welcome credit.",
    request: object({}),
    response: object({
      amountUsd: number2().nullable(),
      amountStoner: number2().nullable(),
      status: string2().nullable(),
      amountSettings: object({
        gold: number2(),
        diamond: number2(),
        owner: number2(),
        vestMonthlyTranches: object({
          gold: number2(),
          diamond: number2(),
          owner: number2()
        })
      }),
      vesting: object({
        totalPendingUsd: number2(),
        totalPaidUsd: number2(),
        totalReturnedUsd: number2(),
        totalPendingStoner: number2(),
        totalPaidStoner: number2(),
        totalReturnedStoner: number2(),
        nextUnlockAt: string2().nullable(),
        nextAmountUsd: number2().nullable(),
        nextAmountStoner: number2().nullable(),
        stopped: boolean2(),
        stoppedNote: string2().nullable(),
        tranches: array(object({
          trancheNo: number2(),
          totalTranches: number2(),
          amountUsd: number2().nullable(),
          amountStoner: number2(),
          dueAt: string2(),
          status: string2(),
          note: string2().nullable()
        }))
      }).nullable(),
      balance: object({
        available: number2(),
        locked: number2(),
        total: number2(),
        pendingUsd: number2(),
        pendingLegacyStoner: number2()
      }),
      yearly: object({
        amountUsd: number2().nullable(),
        amountStoner: number2(),
        status: string2(),
        locked: boolean2()
      }).nullable(),
      yearlyAmountSetting: number2()
    }),
    async handler(ctx) {
      const me = await myUsername(ctx);
      const db = ctx.db();
      await processWelcomeVesting(ctx);
      const rows = await db.select().from(welcomeCredits3).where(eq(welcomeCredits3.username, me)).orderBy(asc(welcomeCredits3.id));
      const welcome = rows.find((r) => r.kind === "welcome") ?? null;
      const yearly = rows.find((r) => r.kind === "yearly") ?? null;
      const amounts = await welcomeCreditAmounts(ctx);
      const vt = (plan) => WELCOME_VEST_MONTHLY_TRANCHES[plan] ?? 0;
      let vesting = null;
      if (welcome) {
        const tranches = await db.select().from(welcomeVesting3).where(eq(welcomeVesting3.welcomeCreditId, welcome.id)).orderBy(asc(welcomeVesting3.trancheNo));
        if (tranches.length > 0) {
          const pending = tranches.filter((t) => t.status === "pending");
          const next = [...pending].sort((a, b) => a.dueAt.getTime() - b.dueAt.getTime())[0] ?? null;
          const stoppedRows = tranches.filter((t) => t.status === "returned" && (t.note ?? "").startsWith("vesting stopped"));
          const anchored = welcome.amountUsd != null;
          const stoppedUsd = stoppedRows.reduce((s, t) => s + (t.amountUsd ?? 0), 0);
          const stoppedStoner = stoppedRows.reduce((s, t) => s + t.amountStoner, 0);
          const paidRows = tranches.filter((t) => t.status === "paid");
          vesting = {
            totalPendingUsd: pending.reduce((s, t) => s + (t.amountUsd ?? 0), 0),
            totalPaidUsd: paidRows.reduce((s, t) => s + (t.amountUsd ?? 0), 0),
            totalReturnedUsd: tranches.filter((t) => t.status === "returned").reduce((s, t) => s + (t.amountUsd ?? 0), 0),
            totalPendingStoner: pending.filter((t) => t.amountUsd == null).reduce((s, t) => s + t.amountStoner, 0),
            totalPaidStoner: paidRows.reduce((s, t) => s + t.amountStoner, 0),
            totalReturnedStoner: tranches.filter((t) => t.status === "returned").reduce((s, t) => s + t.amountStoner, 0),
            nextUnlockAt: next ? next.dueAt.toISOString() : null,
            nextAmountUsd: next ? next.amountUsd : null,
            nextAmountStoner: next ? next.amountStoner : null,
            stopped: stoppedRows.length > 0,
            stoppedNote: stoppedRows.length > 0 ? anchored ? `vesting stopped \u2014 subscription ended; ${usdText(stoppedUsd)} of credit value returned to the driver earning pool` : `vesting stopped \u2014 subscription ended; ${stoppedStoner} $STONER returned to the driver earning pool` : null,
            tranches: tranches.map((t) => ({
              trancheNo: t.trancheNo,
              totalTranches: t.totalTranches,
              amountUsd: t.amountUsd,
              amountStoner: t.amountStoner,
              dueAt: t.dueAt.toISOString(),
              status: t.status,
              note: t.note ?? null
            }))
          };
        }
      }
      const vestingUsdTotal = vesting ? vesting.totalPendingUsd + vesting.totalPaidUsd + vesting.totalReturnedUsd : 0;
      const vestingLegacyTotal = vesting ? vesting.totalPendingStoner + vesting.totalPaidStoner + vesting.totalReturnedStoner : 0;
      const headPaid = welcome && welcome.status === "paid" ? welcome.amountStoner : 0;
      const yearlyPaid = yearly && yearly.status === "paid" ? yearly.amountStoner : 0;
      const yearlyUnlocked = yearlyPaid > 0 && yearly != null && !yearly.locked;
      const yearlyStillLocked = yearlyPaid > 0 && yearly != null && yearly.locked;
      const available = headPaid + (vesting?.totalPaidStoner ?? 0) + (yearlyUnlocked ? yearlyPaid : 0);
      const locked = yearlyStillLocked ? yearlyPaid : 0;
      return {
        amountUsd: welcome?.amountUsd != null ? welcome.amountUsd + vestingUsdTotal : null,
        amountStoner: welcome != null && welcome.amountUsd == null ? welcome.amountStoner + vestingLegacyTotal : null,
        status: welcome?.status ?? null,
        amountSettings: {
          gold: amounts.gold,
          diamond: amounts.diamond,
          owner: amounts.owner,
          vestMonthlyTranches: { gold: vt("gold"), diamond: vt("diamond"), owner: vt("owner") }
        },
        vesting,
        balance: {
          available,
          locked,
          total: available + locked,
          pendingUsd: vesting?.totalPendingUsd ?? 0,
          pendingLegacyStoner: vesting?.totalPendingStoner ?? 0
        },
        yearly: yearly ? {
          amountUsd: yearly.amountUsd,
          amountStoner: yearly.amountStoner,
          status: yearly.status,
          locked: yearly.locked
        } : null,
        yearlyAmountSetting: await yearlyCreditAmount(ctx)
      };
    }
  }),
