  payTeamReward: defineAction({
    description: "Pay team reward.",
    request: object({
      username: string2().min(1).max(40),
      amountStoner: number2().positive().max(1e8),
      note: string2().max(200).optional()
    }),
    response: object({ ok: boolean2(), error: string2().nullable() }),
    async handler(ctx, args) {
      const db = ctx.db();
      if (!await isBetaOwner(ctx))
        return { ok: false, error: "Only the owner (admin) can pay team rewards." };
      const balance = await rewardWalletBalance(ctx);
      if (balance < args.amountStoner)
        return {
          ok: false,
          error: `The reward wallet holds ${balance} $STONER \u2014 it can't pay ${args.amountStoner}. Rewards only ever pay what's actually held.`
        };
      const to = args.username.trim().replace(/^@/, "");
      if (!to)
        return { ok: false, error: "Enter the username to pay." };
      await db.insert(rewardWalletLedger3).values({
        kind: "team_reward",
        amountStoner: -args.amountStoner,
        username: to,
        note: args.note?.trim() || "Team reward"
      });
      await appendChain(ctx, {
        refKind: "driver",
        refId: null,
        sessionId: null,
        event: "team_reward_paid",
        payload: {
          username: to,
          amountStoner: args.amountStoner,
          reason: "team_reward",
          at: new Date().toISOString()
        }
      });
      ctx.invalidateQueries();
      return { ok: true, error: null };
    }
  }),
