  setTripQueueStatus: defineAction({
    description: "Set trip queue status.",
    request: object({
      id: number2().int().positive(),
      status: _enum(["planned", "active", "paused"])
    }),
    response: object({ ok: boolean2(), error: string2().nullable() }),
    async handler(ctx, args) {
      const db = ctx.db();
      const rows = await db.select().from(tripQueue3).where(eq(tripQueue3.id, args.id)).limit(1);
      const row = rows[0];
      if (!row)
        return { ok: false, error: "That trip doesn't exist." };
      if (row.status === "completed")
        return { ok: false, error: "That trip is completed \u2014 its record is sealed." };
      if (args.status === "active") {
        const all = await db.select().from(tripQueue3);
        const other = all.find((t) => t.status === "active" && t.id !== args.id);
        if (other) {
          return {
            ok: false,
            error: `\u201C${other.name}\u201D is your active trip right now. Pause it (its logged miles stay saved on this device, ready to resume) or complete it (Stop trip & save sheet) before starting \u201C${row.name}\u201D. Nothing was switched.`
          };
        }
      }
      const patch = {
        status: args.status,
        updatedAt: new Date
      };
      if (args.status === "active" && !row.startedAt)
        patch.startedAt = new Date;
      await db.update(tripQueue3).set(patch).where(eq(tripQueue3.id, args.id));
      await appendChain(ctx, {
        refKind: "trip",
        refId: null,
        sessionId: null,
        event: args.status === "active" ? "trip_queue_activated" : args.status === "paused" ? "trip_queue_paused" : "trip_queue_planned",
        payload: { queueId: args.id, name: row.name, status: args.status, at: new Date().toISOString() }
      });
      ctx.invalidateQueries();
      return { ok: true, error: null };
    }
  }),
