      const mine = await myMembership(ctx, me);
      const emptyTotals = { invoiced: 0, collected: 0, outstanding: 0, windowCount: 0, warningCount: 0, revokedCount: 0, paidCount: 0 };
      if (!mine || mine.role !== "owner" && mine.role !== "dispatch") {
        return { canView: false, companyName: null, myUsername: me, invoices: [], totals: emptyTotals };
      }
