  confirmIntelReport: defineAction({
    description: "Confirm intel report.",
    request: object({
      id: number2().int().positive(),
      lat: number2(),
      lon: number2()
    }),
    response: object({
      ok: literal(true),
      confirmed: boolean2(),
      pointsAwarded: number2(),
      reason: string2().nullable()
    }),
    async handler(ctx, args) {
      const db = ctx.db();
      const rows = await db.select().from(intelReports3).where(eq(intelReports3.id, args.id)).limit(1);
      const row = rows[0];
      if (!row)
        return { ok: true, confirmed: false, pointsAwarded: 0, reason: "Report not found." };
      const retiredRows = await db.select({ placeId: roadPlaceRetired3.placeId }).from(roadPlaceRetired3).where(eq(roadPlaceRetired3.placeId, `intel-${args.id}`)).limit(1);
      if (retiredRows.length > 0)
        return {
          ok: true,
          confirmed: false,
          pointsAwarded: 0,
          reason: "That spot was marked 'Not here' and retired \u2014 it no longer shows or confirms."
        };
      if (row.confirmedAt)
        return { ok: true, confirmed: true, pointsAwarded: 0, reason: "Already confirmed." };
      if (Date.now() - row.createdAt.getTime() < 10 * 60000) {
        return {
          ok: true,
          confirmed: false,
          pointsAwarded: 0,
          reason: "Too soon \u2014 a report confirms on a later pass, at least 10 minutes after it was dropped."
        };
      }
      const distMi = haversineMiServer(args.lat, args.lon, row.lat, row.lon);
      if (distMi > 0.25) {
        return {
          ok: true,
          confirmed: false,
          pointsAwarded: 0,
          reason: "Your GPS isn't at the reported spot \u2014 confirmation needs a real pass within a quarter mile."
        };
      }
      const me = await myUsername(ctx);
      const pointsAwarded = await awardDailyTask(ctx, {
        username: me,
        task: "intel",
        reason: `Road intel confirmed by your GPS pass (${row.kind.replace(/_/g, " ")})`,
        refSuffix: `-intel${row.id}`
      });
      await db.update(intelReports3).set({ confirmedAt: new Date, points: pointsAwarded }).where(eq(intelReports3.id, args.id));
      ctx.invalidateQueries();
      return { ok: true, confirmed: true, pointsAwarded, reason: null };
    }
  }),
