  listWeighStationStatuses: defineAction({
    description: "List weigh station statuses.",
    request: object({
      stationIds: array(string2().min(1).max(80)).max(60)
    }),
    response: object({
      statuses: array(object({
        stationId: string2(),
        stationName: string2(),
        status: _enum(["open", "closed", "unknown"]),
        updatedAt: string2().nullable(),
        ageMin: number2().nullable(),
        reportCount: number2(),
        reporter: string2().nullable(),
        driverReported: boolean2(),
        addedBy: string2().nullable(),
        addedAt: string2().nullable(),
        notHereHidden: boolean2(),
        notHereRetired: boolean2()
      }))
    }),
    async handler(ctx, args) {
      const db = ctx.db();
      const now = Date.now();
      if (args.stationIds.length === 0)
        return { statuses: [] };
      const me = await myUsername(ctx);
      const { hidden: hiddenPlaces, retired: retiredPlaces } = await notHereSetsFor(ctx, me);
      const rows = await db.select().from(weighStationStatus3).where(inArray(weighStationStatus3.stationId, args.stationIds));
      const byId = new Map(rows.map((r) => [r.stationId, r]));
      const driverRows = await db.select().from(driverWeighStations3).where(inArray(driverWeighStations3.stationId, args.stationIds));
      const driverById = new Map(driverRows.map((r) => [r.stationId, r]));
      return {
        statuses: args.stationIds.map((id) => {
          const drv = driverById.get(id);
          const origin = {
            driverReported: drv != null,
            addedBy: drv?.reporter ?? null,
            addedAt: drv ? drv.createdAt.toISOString() : null
          };
          const notHere = {
            notHereHidden: hiddenPlaces.has(id),
            notHereRetired: retiredPlaces.has(id)
          };
          const row = byId.get(id);
          if (!row) {
            return {
              stationId: id,
              stationName: drv?.stationName ?? "",
              status: "unknown",
              updatedAt: null,
              ageMin: null,
              reportCount: 0,
              reporter: null,
              ...origin,
              ...notHere
            };
          }
          const updatedMs = row.updatedAt.getTime();
          return {
            stationId: row.stationId,
            stationName: row.stationName,
            status: effectiveWeighStatus(row.status, updatedMs, now),
            updatedAt: row.updatedAt.toISOString(),
            ageMin: weighStatusAgeMin(updatedMs, now),
            reportCount: row.reportCount,
            reporter: row.reporter,
            ...origin,
            ...notHere
          };
        })
      };
    }
  }),
