  reportStationHere: defineAction({
    description: "Report a weigh station at the driver's position (Station here).",
    request: object({
      status: _enum(["open", "closed"]),
      stationName: string2().min(1).max(120),
      lat: number2(),
      lon: number2(),
      knownStations: array(object({
        stationId: string2().min(1).max(80),
        stationName: string2().min(1).max(120),
        lat: number2(),
        lon: number2()
      })).max(80)
    }),
    response: object({
      ok: literal(true),
      created: boolean2(),
      stationId: string2(),
      stationName: string2(),
      verified: boolean2(),
      pointsAwarded: number2()
    }),
    async handler(ctx, args) {
      const db = ctx.db();
      const me = await myUsername(ctx);
      const driverRows = await db.select().from(driverWeighStations3);
      const statusRows = await db.select({
        stationId: weighStationStatus3.stationId,
        stationName: weighStationStatus3.stationName,
        lat: weighStationStatus3.lat,
        lon: weighStationStatus3.lon
      }).from(weighStationStatus3);
      const byId = new Map;
      for (const s of args.knownStations)
        byId.set(s.stationId, s);
      for (const r of statusRows)
        if (!byId.has(r.stationId))
          byId.set(r.stationId, r);
      for (const r of driverRows) {
        byId.set(r.stationId, { stationId: r.stationId, stationName: r.stationName, lat: r.lat, lon: r.lon });
      }
      const { retired: retiredPlaces } = await notHereSetsFor(ctx, me);
      const plan = planStationHereReport(excludeRetiredCandidates([...byId.values()], retiredPlaces), {
        lat: args.lat,
        lon: args.lon
      });
      const created = plan.kind === "create";
      const stationId = created ? `driver-${crypto.randomUUID()}` : plan.stationId;
      const target = created ? null : byId.get(stationId);
      const stationName = created ? args.stationName : target?.stationName ?? args.stationName;
      const stationLat = created ? args.lat : target?.lat ?? args.lat;
      const stationLon = created ? args.lon : target?.lon ?? args.lon;
      if (created) {
        await db.insert(driverWeighStations3).values({
          stationId,
          stationName,
          lat: args.lat,
          lon: args.lon,
          reporter: me
        });
      }
      const distMi = haversineMiServer(args.lat, args.lon, stationLat, stationLon);
      const verified = weighReportVerified(distMi);
      const inserted = await db.insert(weighStationReports3).values({
        stationId,
        stationName,
        status: args.status,
        reporter: me,
        lat: args.lat,
        lon: args.lon,
        stationLat,
        stationLon,
        verified,
        pointsAwarded: 0
      }).returning({ id: weighStationReports3.id });
      const report = inserted[0];
      if (!report)
        throw new Error("reportStationHere: insert returned no rows");
      let pointsAwarded = 0;
      if (verified) {
        pointsAwarded = await awardDailyTask(ctx, {
          username: me,
          task: "intel",
          reason: created ? `Weigh station added by driver report and marked ${args.status} (${stationName})` : `Weigh station reported ${args.status} at the station (${stationName})`,
          refSuffix: `-weigh${report.id}`
        });
        if (pointsAwarded > 0) {
          await db.update(weighStationReports3).set({ pointsAwarded }).where(eq(weighStationReports3.id, report.id));
        }
      }
      const existing = await db.select({ reportCount: weighStationStatus3.reportCount }).from(weighStationStatus3).where(eq(weighStationStatus3.stationId, stationId)).limit(1);
      await db.insert(weighStationStatus3).values({
        stationId,
        stationName,
        lat: stationLat,
        lon: stationLon,
        status: args.status,
        reporter: me,
        reportCount: (existing[0]?.reportCount ?? 0) + 1,
        updatedAt: new Date
      }).onConflictDoUpdate({
        target: weighStationStatus3.stationId,
        set: {
          stationName,
          lat: stationLat,
          lon: stationLon,
          status: args.status,
          reporter: me,
          reportCount: (existing[0]?.reportCount ?? 0) + 1,
          updatedAt: new Date
        }
      });
      ctx.invalidateQueries();
      return { ok: true, created, stationId, stationName, verified, pointsAwarded };
    }
  }),
  markPlaceNotHere: defineAction({
    description: "Mark a road-intel place as not here (hide / delete / retire).",
    request: object({
      placeId: string2().min(1).max(120),
      lat: number2(),
      lon: number2()
    }),
    response: object({
      ok: literal(true),
      outcome: _enum(["hidden", "deleted", "retired"]),
      placeId: string2(),
      correctionCount: number2()
    }),
    async handler(ctx, args) {
      const db = ctx.db();
      const me = await myUsername(ctx);
      const placeId = args.placeId;
      const placeKind = roadPlaceKindForId(placeId);
      const retiredExisting = await db.select().from(roadPlaceRetired3).where(eq(roadPlaceRetired3.placeId, placeId)).limit(1);
      const existingCorrections = await db.select().from(roadPlaceCorrections3).where(eq(roadPlaceCorrections3.placeId, placeId));
      const existingReporters = [...new Set(existingCorrections.map((c) => c.reporter))];
      if (retiredExisting[0]) {
        await db.insert(roadPlaceHides3).values({ placeId, username: me }).onConflictDoNothing();
        ctx.invalidateQueries();
        return {
          ok: true,
          outcome: retiredExisting[0].reason === "creator_deleted" ? "deleted" : "retired",
          placeId,
          correctionCount: existingReporters.length
        };
      }
      let creator = null;
      const intelId = intelReportIdForPlaceId(placeId);
      if (placeKind === "driver_weigh_station") {
        const rows = await db.select({ reporter: driverWeighStations3.reporter }).from(driverWeighStations3).where(eq(driverWeighStations3.stationId, placeId)).limit(1);
        creator = rows[0]?.reporter ?? null;
      } else if (placeKind === "intel_report" && intelId != null) {
        const rows = await db.select({ reporter: intelReports3.reporter }).from(intelReports3).where(eq(intelReports3.id, intelId)).limit(1);
        creator = rows[0]?.reporter ?? null;
      }
      const plan = planNotHereCorrection({ reporter: me, creator, existingReporters });
      await db.insert(roadPlaceHides3).values({ placeId, username: me }).onConflictDoNothing();
      if (!plan.alreadyMarked) {
        await db.insert(roadPlaceCorrections3).values({
          placeId,
          placeKind,
          reporter: me,
          reporterLat: args.lat,
          reporterLon: args.lon,
          outcome: plan.outcome
        });
        if (plan.outcome === "deleted") {
          if (placeKind === "driver_weigh_station") {
            await db.delete(driverWeighStations3).where(eq(driverWeighStations3.stationId, placeId));
            await db.delete(weighStationStatus3).where(eq(weighStationStatus3.stationId, placeId));
          } else if (placeKind === "intel_report" && intelId != null) {
            await db.delete(intelReports3).where(eq(intelReports3.id, intelId));
          }
          await db.insert(roadPlaceRetired3).values({
            placeId,
            placeKind,
            reason: "creator_deleted",
            correctionCount: plan.distinctReporters
          }).onConflictDoNothing();
        } else if (plan.outcome === "retired") {
          await db.insert(roadPlaceRetired3).values({
            placeId,
            placeKind,
            reason: "threshold",
            correctionCount: plan.distinctReporters
          }).onConflictDoNothing();
        }
        await appendChain(ctx, {
          refKind: "driver",
          refId: null,
          sessionId: null,
          event: "road_place_not_here",
          payload: {
            placeId,
            placeKind,
            reporter: me,
            reporterLat: args.lat,
            reporterLon: args.lon,
            outcome: plan.outcome,
            distinctReporters: plan.distinctReporters,
            at: new Date().toISOString()
          }
        });
      }
      ctx.invalidateQueries();
      return { ok: true, outcome: plan.outcome, placeId, correctionCount: plan.distinctReporters };
    }
  }),
