  recordRecentDestination: defineAction({
    description: "Record recent destination.",
    request: object({
      label: string2().trim().min(1).max(300),
      lat: number2().min(-90).max(90),
      lon: number2().min(-180).max(180),
      gateLat: number2().min(-90).max(90).nullable(),
      gateLon: number2().min(-180).max(180).nullable()
    }),
    response: object({ ok: literal(true), id: number2() }),
    async handler(ctx, args) {
      const db = ctx.db();
      const rows = await db.select().from(recentDestinations3);
      const targetLat = args.gateLat ?? args.lat;
      const targetLon = args.gateLon ?? args.lon;
      const existing = rows.find((r) => {
        const rLat = r.gateLat ?? r.lat;
        const rLon = r.gateLon ?? r.lon;
        return haversineMiServer(targetLat, targetLon, rLat, rLon) < 0.02;
      });
      if (existing) {
        await db.update(recentDestinations3).set({
          label: args.label,
          lat: args.lat,
          lon: args.lon,
          gateLat: args.gateLat != null && args.gateLon != null ? args.gateLat : null,
          gateLon: args.gateLat != null && args.gateLon != null ? args.gateLon : null,
          useCount: existing.useCount + 1,
          lastUsedAt: new Date
        }).where(eq(recentDestinations3.id, existing.id));
        ctx.invalidateQueries();
        return { ok: true, id: existing.id };
      }
      const inserted = await db.insert(recentDestinations3).values({
        label: args.label,
        lat: args.lat,
        lon: args.lon,
        gateLat: args.gateLat != null && args.gateLon != null ? args.gateLat : null,
        gateLon: args.gateLat != null && args.gateLon != null ? args.gateLon : null
      }).returning({ id: recentDestinations3.id });
      const row = inserted[0];
      if (!row)
        throw new Error("recordRecentDestination: insert returned no rows");
      const all = await db.select({ id: recentDestinations3.id }).from(recentDestinations3).orderBy(desc(recentDestinations3.lastUsedAt));
      for (const extra of all.slice(25)) {
        await db.delete(recentDestinations3).where(eq(recentDestinations3.id, extra.id));
      }
      ctx.invalidateQueries();
      return { ok: true, id: row.id };
    }
  }),
