  sendChatMessage: defineAction({
    description: "Send chat message.",
    request: object({
      groupId: number2().int().positive(),
      kind: _enum(["text", "load", "route", "location"]),
      body: string2().min(1).max(2000),
      payload: string2().max(4000).nullable()
    }),
    response: object({ id: number2() }),
    async handler(ctx, args) {
      const db = ctx.db();
      const dm = await dmMembership(ctx, args.groupId);
      if (dm.isDm && !dm.isMember)
        throw new Error("That DM is private to its two drivers \u2014 nobody else can post in it.");
      const prof = await db.select().from(profile3).where(eq(profile3.id, myProfileId(ctx))).limit(1);
      const sender = prof[0]?.chatName ?? "Driver";
      const r = await db.insert(chatMessages3).values({
        groupId: args.groupId,
        sender,
        kind: args.kind,
        body: args.body,
        payload: args.payload
      }).returning({ id: chatMessages3.id });
      const inserted = r[0];
      if (!inserted)
        throw new Error("sendChatMessage: insert returned no rows");
      await db.insert(chatReads3).values({ groupId: args.groupId, lastReadId: inserted.id }).onConflictDoUpdate({
        target: chatReads3.groupId,
        set: { lastReadId: inserted.id }
      });
      ctx.invalidateQueries();
      return { id: inserted.id };
    }
  }),
