  getOrCreateDm: defineAction({
    description: "Get or create dm.",
    request: object({ username: string2().min(1).max(40) }),
    response: object({
      groupId: number2().nullable(),
      error: string2().nullable()
    }),
    async handler(ctx, args) {
      const db = ctx.db();
      const prof = await db.select().from(profile3).where(eq(profile3.id, myProfileId(ctx))).limit(1);
      const me = prof[0]?.socialUsername ?? "driver";
      if (args.username.toLowerCase() === me.toLowerCase())
        return { groupId: null, error: "That's you." };
      const rows = await db.select().from(socialUsers3);
      const target = rows.find((r) => r.username.toLowerCase() === args.username.toLowerCase());
      const policy = target?.dmPolicy ?? "everyone";
      if (policy === "nobody")
        return { groupId: null, error: `${args.username} isn't accepting DMs right now.` };
      if (policy === "following") {
        const allFollows = await db.select().from(follows3);
        const theyFollowMe = allFollows.some((f) => f.follower.toLowerCase() === args.username.toLowerCase() && f.followee.toLowerCase() === me.toLowerCase());
        if (!theyFollowMe)
          return {
            groupId: null,
            error: `${args.username} only accepts DMs from people they follow.`
          };
      }
      const dmGroups = await db.select().from(chatGroups3).where(eq(chatGroups3.kind, "dm"));
      const members = await db.select().from(chatMembers3);
      for (const g of dmGroups) {
        const ms = members.filter((m) => m.groupId === g.id).map((m) => m.username.toLowerCase());
        if (ms.length === 2 && ms.includes(me.toLowerCase()) && ms.includes(args.username.toLowerCase())) {
          return { groupId: g.id, error: null };
        }
      }
      const r = await db.insert(chatGroups3).values({ name: args.username, kind: "dm", createdBy: me }).returning({ id: chatGroups3.id });
      const gid = r[0]?.id;
      if (gid == null)
        return { groupId: null, error: "Couldn't open the DM." };
      await db.insert(chatMembers3).values({ groupId: gid, username: me });
      await db.insert(chatMembers3).values({ groupId: gid, username: args.username });
      ctx.invalidateQueries();
      return { groupId: gid, error: null };
    }
  }),
