  saveCompanySetup: defineAction({
    description: "Save company setup.",
    request: object({
      legalName: string2().max(120).nullable(),
      dba: string2().max(120).nullable(),
      address: string2().max(300).nullable(),
      ein: string2().max(20).nullable(),
      mcNumber: string2().max(30).nullable(),
      usdotNumber: string2().max(30).nullable(),
      contactName: string2().max(80).nullable(),
      contactEmail: string2().max(120).nullable(),
      contactPhone: string2().max(40).nullable(),
      fleetSize: number2().int().nonnegative().nullable()
    }),
    response: object({ ok: boolean2(), error: string2().nullable(), complete: boolean2() }),
    async handler(ctx, args) {
      const db = ctx.db();
      const me = await myUsername(ctx);
      const mine = await myMembership(ctx, me);
      if (!mine || mine.role !== "owner")
        return { ok: false, error: "Only the company owner completes company setup.", complete: false };
      const existingEarly = await db.select().from(companySetup3).where(eq(companySetup3.companyId, mine.company.id)).limit(1);
      const einRaw = args.ein?.trim() || null;
      let einStored = existingEarly[0]?.ein ?? null;
      if (einRaw && !looksLikeEinMask(einRaw)) {
        const digits = einRaw.replace(/\D/g, "");
        if (digits.length !== 9)
          return { ok: false, error: "That EIN doesn't look right \u2014 an EIN is 9 digits (XX-XXXXXXX). Nothing was saved.", complete: false };
        einStored = await encryptPii(ctx, digits);
      } else if (!einRaw) {
        einStored = null;
      }
      const fields = {
        legalName: args.legalName?.trim() || null,
        dba: args.dba?.trim() || null,
        address: args.address?.trim() || null,
        ein: einStored,
        mcNumber: args.mcNumber?.trim() || null,
        usdotNumber: args.usdotNumber?.trim() || null,
        contactName: args.contactName?.trim() || null,
        contactEmail: args.contactEmail?.trim() || null,
        contactPhone: args.contactPhone?.trim() || null,
        fleetSize: args.fleetSize
      };
      const docs = await db.select().from(companyDocs3).where(eq(companyDocs3.companyId, mine.company.id));
      const kinds = new Set(docs.filter((d) => d.subjectUsername === "company").map((d) => d.kind));
      const fieldsDone = Boolean(fields.legalName && fields.address && fields.ein && fields.mcNumber && fields.usdotNumber && fields.contactName && fields.contactEmail && fields.fleetSize != null);
      const complete = fieldsDone && kinds.has("w9") && kinds.has("authority") && kinds.has("insurance");
      const existing = await db.select().from(companySetup3).where(eq(companySetup3.companyId, mine.company.id)).limit(1);
      if (existing[0]) {
        await db.update(companySetup3).set({ ...fields, complete, updatedAt: new Date }).where(eq(companySetup3.companyId, mine.company.id));
      } else {
        await db.insert(companySetup3).values({ companyId: mine.company.id, ...fields, complete });
      }
      ctx.invalidateQueries();
      return { ok: true, error: null, complete };
    }
  }),
  uploadCompanyDoc: defineAction({
    description: "Upload company doc.",
    request: object({
      kind: _enum(["w9", "authority", "insurance", "driver_w9"]),
      filename: string2().min(1).max(160),
      mime: string2().max(80).nullable(),
      dataBase64: string2().min(1),
      expiresAt: string2().nullable()
    }),
    response: object({ ok: boolean2(), error: string2().nullable() }),
    async handler(ctx, args) {
      const db = ctx.db();
      const me = await myUsername(ctx);
      const mine = await myMembership(ctx, me);
      if (!mine)
        return { ok: false, error: "Join or create a company first." };
      const isCompanyDoc = args.kind !== "driver_w9";
      if (isCompanyDoc && mine.role !== "owner")
        return { ok: false, error: "Only the owner uploads company tax and authority documents." };
      const bytes = base64ToBytes(args.dataBase64);
      if (bytes.length === 0 || bytes.length > 12 * 1024 * 1024)
        return { ok: false, error: "That file is empty or over the 12 MB limit." };
      const key = `company-docs/${mine.company.id}/${args.kind}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      await ctx.blobs.put(key, new Uint8Array(bytes), { contentType: args.mime ?? "application/octet-stream" });
      await db.insert(companyDocs3).values({
        companyId: mine.company.id,
        subjectUsername: isCompanyDoc ? "company" : me,
        kind: args.kind,
        filename: args.filename,
        mime: args.mime,
        blobKey: key,
        status: "uploaded",
        expiresAt: args.expiresAt ? new Date(args.expiresAt) : null
      });
      ctx.invalidateQueries();
      return { ok: true, error: null };
    }
  }),
  getCompanyDoc: defineAction({
    description: "Get company doc.",
    request: object({ id: number2().int().positive() }),
    response: object({ url: string2().nullable(), mime: string2().nullable() }),
    async handler(ctx, args) {
      const db = ctx.db();
      const me = await myUsername(ctx);
      const mine = await myMembership(ctx, me);
      if (!mine)
        return { url: null, mime: null };
      const rows = await db.select().from(companyDocs3).where(eq(companyDocs3.id, args.id)).limit(1);
      const doc = rows[0];
      if (!doc || doc.companyId !== mine.company.id)
        return { url: null, mime: null };
      const canView = mine.role === "owner" || mine.role === "dispatch" || doc.subjectUsername === me;
      if (!canView)
        return { url: null, mime: null };
      if (doc.subjectUsername !== me && doc.subjectUsername !== "company") {
        await db.insert(recordAccessLog3).values({
          viewerUsername: me,
          subjectUsername: doc.subjectUsername,
          kind: "view",
          what: `document: ${doc.kind} (${doc.filename})`
        });
        await appendChain(ctx, {
          refKind: "driver",
          refId: null,
          sessionId: null,
          event: "record_access",
          payload: {
            viewerUsername: me,
            viewerRole: mine.role,
            subjectUsername: doc.subjectUsername,
            kind: "view",
            what: `document: ${doc.kind} (${doc.filename})`,
            at: new Date().toISOString()
          }
        });
      }
      await appendChain(ctx, {
        refKind: "driver",
        refId: null,
        sessionId: null,
        event: "portal_access",
        payload: {
          viewerUsername: me,
          targetUsername: doc.subjectUsername,
          what: `document: ${doc.kind} (${doc.filename})`,
          at: new Date().toISOString()
        }
      });
      const url = await ctx.blobs.getUrl(doc.blobKey);
      return { url, mime: doc.mime };
    }
  }),
