  extractMoneyDoc: defineAction({
    description: "Extract money doc.",
    request: object({
      kind: _enum(["fuel", "expense", "settlement"]),
      dataBase64: string2().min(1).max(14000000),
      mimeType: _enum(["image/jpeg", "image/png"])
    }),
    response: object({
      found: boolean2(),
      station: string2().nullable(),
      vendor: string2().nullable(),
      state: string2().nullable(),
      gallons: number2().nullable(),
      pricePerGallon: number2().nullable(),
      total: number2().nullable(),
      amount: number2().nullable(),
      carrier: string2().nullable(),
      periodLabel: string2().nullable(),
      gross: number2().nullable(),
      net: number2().nullable(),
      lines: array(object({ label: string2(), amount: number2() }))
    }),
    async handler(ctx, args) {
      const s = object({
        found: boolean2().describe("True only if the document visibly is the requested kind of document with readable money details."),
        station: string2().nullable().describe("Fuel station / truck stop name exactly as printed, else null"),
        vendor: string2().nullable().describe("Vendor / payee name exactly as printed, else null"),
        state: string2().nullable().describe("US state as the full state name when shown or shown as abbreviation, else null"),
        gallons: number2().nullable().describe("Gallons pumped as printed (number only), else null"),
        pricePerGallon: number2().nullable().describe("Price per gallon as printed (number only), else null"),
        total: number2().nullable().describe("Total charged as printed (number only), else null"),
        amount: number2().nullable().describe("For an expense receipt: the total amount as printed, else null"),
        carrier: string2().nullable().describe("For a settlement: the carrier/company name exactly as printed, else null"),
        periodLabel: string2().nullable().describe("For a settlement: the pay period exactly as printed, else null"),
        gross: number2().nullable().describe("For a settlement: gross pay as printed, else null"),
        net: number2().nullable().describe("For a settlement: net pay as printed, else null"),
        lines: array(object({ label: string2(), amount: number2() })).describe("For a settlement: every pay/deduction line visibly printed, label exactly as printed and signed amount (deductions negative). Empty for other kinds.")
      });
      const kindText = args.kind === "fuel" ? "a fuel receipt from a truck stop" : args.kind === "expense" ? "an expense receipt (tolls, lumper, maintenance, scale, parking, or similar)" : "a carrier settlement / pay statement for a truck driver";
      const result = await ctx.inference.complete(`Read this document \u2014 it should be ${kindText}. Extract ONLY details visibly printed on it. Do not guess or fill in anything not shown: any detail that is not printed must be null (or an empty list). If it is not this kind of document or has no readable money details, report found as false.`, { schema: s, images: [{ dataBase64: args.dataBase64, mimeType: args.mimeType, filename: "money-document" }] });
      return result;
    }
  }),
