  acceptPayStub: defineAction({
    description: "Accept pay stub.",
    request: object({ id: number2().int().positive() }),
    response: object({ ok: boolean2(), error: string2().nullable(), payEntryId: number2().nullable(), stubEmail: stubEmailSummaryShape }),
    privileged: [privileged.docEmailConfig, privileged.sendDocEmail],
    async handler(ctx, args) {
      const db = ctx.db();
      const me = await myUsername(ctx);
      const rows = await db.select().from(payStubDeliveries3).where(eq(payStubDeliveries3.id, args.id)).limit(1);
      const d = rows[0];
      if (!d || d.recipientUsername !== me) {
        return { ok: false, error: "That stub isn't in your inbox.", payEntryId: null, stubEmail: NO_STUB_EMAIL };
      }
      const gate = acceptGate(d.status);
      if (!gate.allowed)
        return { ok: false, error: gate.error, payEntryId: d.payEntryId, stubEmail: NO_STUB_EMAIL };
      const claimed = await db.update(payStubDeliveries3).set({ status: "accepted", respondedAt: new Date }).where(and(eq(payStubDeliveries3.id, d.id), eq(payStubDeliveries3.status, "sent"))).returning({ id: payStubDeliveries3.id });
      if (claimed.length === 0) {
        const fresh = (await db.select().from(payStubDeliveries3).where(eq(payStubDeliveries3.id, d.id)).limit(1))[0];
        return {
          ok: false,
          error: acceptGate(fresh?.status ?? "accepted").error,
          payEntryId: fresh?.payEntryId ?? null,
          stubEmail: NO_STUB_EMAIL
        };
      }
      const comp = (await db.select().from(companies3).where(eq(companies3.id, d.companyId)).limit(1))[0];
      const payer = comp?.name ?? "Your company";
      const draft = deliveryToPayEntry({
        kind: d.kind,
        deliveryType: d.deliveryType,
        paidAtMs: d.paidAt.getTime(),
        taxYear: d.taxYear,
        gross: d.gross,
        federalWithheld: d.federalWithheld,
        stateWithheld: d.stateWithheld,
        otherDeductions: d.otherDeductions,
        deductionLines: parseDeductionLines(d.deductionLines),
        perDiem: d.perDiem ?? 0,
        notes: d.notes
      });
      const ins = await db.insert(payEntries3).values({
        username: me,
        kind: draft.kind,
        isForm: draft.isForm,
        payer,
        paidAt: new Date(draft.paidAtMs),
        taxYear: draft.taxYear,
        gross: draft.gross,
        federalWithheld: draft.federalWithheld,
        stateWithheld: draft.stateWithheld,
        otherDeductions: draft.otherDeductions,
        deductionLines: draft.deductionLines.length ? JSON.stringify(draft.deductionLines) : null,
        perDiem: draft.perDiem,
        notes: draft.notes,
        stubBlobKey: d.stubBlobKey,
        stubMime: d.stubMime,
        stubSha256: d.stubSha256,
        source: "company",
        deliveryId: d.id
      }).returning({ id: payEntries3.id });
      const entry = ins[0];
      if (!entry)
        throw new Error("acceptPayStub: pay entry insert returned no rows");
      await db.update(payStubDeliveries3).set({ payEntryId: entry.id }).where(eq(payStubDeliveries3.id, d.id));
      await appendChain(ctx, {
        refKind: "driver",
        refId: null,
        sessionId: null,
        event: "pay_entry_logged",
        payload: {
          payEntryId: entry.id,
          kind: draft.kind,
          isForm: draft.isForm,
          payer,
          taxYear: draft.taxYear,
          gross: draft.gross,
          federalWithheld: draft.federalWithheld,
          stateWithheld: draft.stateWithheld,
          otherDeductions: draft.otherDeductions,
          deductionLines: draft.deductionLines,
          perDiem: draft.perDiem,
          stubSha256: d.stubSha256,
          source: "company",
          deliveryId: d.id,
          at: new Date(draft.paidAtMs).toISOString()
        }
      });
      await appendChain(ctx, {
        refKind: "driver",
        refId: null,
        sessionId: null,
        event: "pay_stub_accepted",
        payload: {
          deliveryId: d.id,
          payEntryId: entry.id,
          recipientUsername: me,
          senderUsername: d.senderUsername,
          companyId: d.companyId,
          kind: d.kind,
          deliveryType: d.deliveryType,
          gross: d.gross,
          perDiem: draft.perDiem,
          at: new Date().toISOString()
        }
      });
      let stubEmail = NO_STUB_EMAIL;
      try {
        stubEmail = await maybeEmailPayStubCopy(ctx, {
          payEntryId: entry.id,
          deliveryId: d.id,
          kind: draft.kind,
          isForm: draft.isForm,
          payer,
          paidAtIso: new Date(draft.paidAtMs).toISOString(),
          gross: draft.gross,
          perDiem: draft.perDiem,
          hasStubFile: d.stubBlobKey != null,
          stubSha256: d.stubSha256
        });
      } catch {}
      ctx.invalidateQueries();
      return { ok: true, error: null, payEntryId: entry.id, stubEmail };
    }
  }),
