  previewFleetImport: defineAction({
    description: "Preview fleet import.",
    request: object({
      kind: _enum(["drivers", "trucks", "loads"]),
      text: string2().min(1).max(60000)
    }),
    response: object({
      ok: boolean2(),
      error: string2().nullable(),
      rows: array(object({
        line: number2(),
        raw: string2(),
        ok: boolean2(),
        status: string2(),
        reason: string2(),
        detail: string2().nullable()
      })),
      counts: object({ received: number2(), ready: number2(), rejected: number2() })
    }),
    async handler(ctx, args) {
      const gate = await whiteGloveGate(ctx);
      if (gate.error || !gate.mine)
        return { ok: false, error: gate.error, rows: [], counts: { received: 0, ready: 0, rejected: 0 } };
      const lines = args.text.split(/\r?\n/);
      if (lines.length > 200)
        return { ok: false, error: "That paste is over 200 lines \u2014 split it into smaller batches so every row can be checked and confirmed.", rows: [], counts: { received: lines.length, ready: 0, rejected: 0 } };
      const rows = await parseFleetImport(ctx, gate.mine.company.id, args.kind, lines);
      if (args.kind === "drivers") {
        for (const r of rows) {
          if (!r.ok)
            continue;
          const parts = splitImportLine(r.raw);
          if ((parts[1] ?? "driver").toLowerCase() !== "dispatch")
            continue;
          const username = parts[0];
          const { standing } = await dispatcherStandingFor(ctx, username);
          if (standing.soloEffective) {
            r.ok = false;
            r.status = "rejected";
            r.reason = soloDeskOpenRefusalFor(username);
            r.detail = null;
          }
        }
      }
      return {
        ok: true,
        error: null,
        rows,
        counts: { received: rows.length, ready: rows.filter((r) => r.ok).length, rejected: rows.filter((r) => !r.ok).length }
      };
    }
  }),
  commitFleetImport: defineAction({
    description: "Commit fleet import.",
    request: object({
      kind: _enum(["drivers", "trucks", "loads"]),
      lines: array(string2().max(2000)).min(1).max(200)
    }),
    response: object({
      ok: boolean2(),
      error: string2().nullable(),
      rows: array(object({
        line: number2(),
        raw: string2(),
        ok: boolean2(),
        status: string2(),
        reason: string2(),
        detail: string2().nullable()
      })),
      summary: object({ received: number2(), written: number2(), rejected: number2() }).nullable()
    }),
    async handler(ctx, args) {
      const db = ctx.db();
      const gate = await whiteGloveGate(ctx);
      if (gate.error || !gate.mine)
        return { ok: false, error: gate.error, rows: [], summary: null };
      const companyId = gate.mine.company.id;
      const parsed = await parseFleetImport(ctx, companyId, args.kind, args.lines);
      const results = [];
      let written = 0;
      for (const row of parsed) {
        if (!row.ok) {
          results.push(row);
          continue;
        }
        const parts = splitImportLine(row.raw);
        try {
          if (args.kind === "drivers") {
            const username = parts[0];
            const role = (parts[1] ?? "driver").toLowerCase();
            if (role === "dispatch") {
              const { standing: importStanding } = await dispatcherStandingFor(ctx, username);
              if (importStanding.soloEffective) {
                results.push({ ...row, ok: false, status: "rejected", reason: soloDeskOpenRefusalFor(username), detail: null });
                continue;
              }
            }
            await db.insert(companyMembers3).values({ companyId, username, role });
            const chats = await db.select().from(chatGroups3).where(eq(chatGroups3.companyId, companyId));
            for (const g of chats)
              await db.insert(chatMembers3).values({ groupId: g.id, username });
            results.push({ ...row, status: "written", detail: `@${username} added to the roster as ${role} and dropped into both company chats.` });
          } else if (args.kind === "trucks") {
            const unit = parts[0];
            const detail = parts.length > 1 ? parts.slice(1).join(", ") : null;
            const ins = await db.insert(fleetTrucks3).values({ companyId, unitLabel: unit, detail, createdBy: gate.me }).returning({ id: fleetTrucks3.id });
            results.push({ ...row, status: "written", detail: `${unit} recorded on the fleet truck list (#${ins[0]?.id ?? "?"}).` });
          } else {
            const rateRaw = parts[5] ?? "";
            const weightRaw = parts[6] ?? "";
            const fields = {
              shipper: parts[0] || null,
              pickupCity: parts[1] ?? null,
              pickupState: parts[2] ?? null,
              deliveryCity: parts[3] ?? null,
              deliveryState: parts[4] ?? null,
              pickupText: null,
              deliveryText: null,
              rate: rateRaw ? Number(rateRaw.replace(/[$,]/g, "")) : null,
              weightLbs: weightRaw ? Math.floor(Number(weightRaw.replace(/,/g, ""))) : null,
              commodity: parts[7] || null,
              hazmat: false
            };
            const ins = await db.insert(loads3).values({ ...fields, docBlobKey: null, docMime: null, docSha256: null }).returning({ id: loads3.id });
            const loadId = ins[0]?.id ?? null;
            await appendChain(ctx, {
              refKind: "load",
              refId: loadId,
              sessionId: null,
              event: "load_saved",
              payload: { ...fields, source: "white_glove_onboarding_import" }
            });
            results.push({ ...row, status: "written", detail: `Opening load #${loadId ?? "?"} created \u2014 Booked, in All loads and the Load Tracker.` });
          }
          written++;
        } catch {
          results.push({ ...row, ok: false, status: "error", reason: "That row couldn't be saved (a database error) \u2014 it was not imported; check it and try again.", detail: null });
        }
      }
      const summary = { received: parsed.length, written, rejected: parsed.length - written };
      await appendChain(ctx, {
        refKind: "driver",
        refId: null,
        sessionId: null,
        event: "fleet_import_completed",
        payload: { by: gate.me, kind: args.kind, ...summary, at: new Date().toISOString() }
      });
      ctx.invalidateQueries();
      return { ok: true, error: null, rows: results, summary };
    }
  }),
