  requestCashout: defineAction({
    description: "Request cashout.",
    request: object({
      amountStoner: number2().positive().max(1e7),
      lane: _enum(["instant", "standard"]),
      pin: string2().max(8).optional(),
      totpCode: string2().max(12).optional()
    }),
    response: object({
      ok: boolean2(),
      status: _enum(["refused", "review_hold", "step_up_required"]),
      error: string2().nullable(),
      holdId: number2().nullable()
    }),
    async handler(ctx, args) {
      const me = await myUsername(ctx);
      await settleAccountLifecycle(ctx, me);
      const cashoutRefusal = moneyExitRefusal("cashout", await myStanding(ctx));
      if (cashoutRefusal) {
        return { ok: false, status: "refused", error: cashoutRefusal, holdId: null };
      }
      const usdValue = null;
      const thresholdHit = usdValue != null ? usdValue >= STEPUP_CASHOUT_THRESHOLD_USD : args.amountStoner >= STEPUP_CASHOUT_THRESHOLD_USD;
      const stepUp = await evaluateMoneyStepUp(ctx, {
        username: me,
        kind: "cashout",
        amountStoner: args.amountStoner,
        thresholdHit,
        pin: args.pin,
        totpCode: args.totpCode
      });
      if (stepUp.outcome === "step_up_required") {
        return { ok: false, status: "step_up_required", error: stepUp.error, holdId: null };
      }
      if (stepUp.outcome === "hold") {
        const reason = usdValue == null && thresholdHit && !stepUp.reason.startsWith("Velocity") ? `${stepUp.reason} (No live $STONER price exists pre-launch, so the $250 threshold was checked against the requested amount itself.)` : stepUp.reason;
        const holdId = await placeMoneyHold(ctx, {
          username: me,
          kind: "cashout",
          amountStoner: args.amountStoner,
          points: null,
          reason
        });
        ctx.invalidateQueries();
        return {
          ok: false,
          status: "review_hold",
          error: `Review Hold placed (hold #${holdId}): ${reason} The cash-out itself did not run \u2014 cash-out activates at go-live with the licensed payout provider, and a held request still needs that gate open. No money moved.`,
          holdId
        };
      }
      return {
        ok: false,
        status: "refused",
        error: "Cash-out isn't live yet. It activates at go-live with the licensed payout provider \u2014 until then no cash-out is requested, promised, or queued. Your balance stays exactly where it is.",
        holdId: null
      };
    }
  }),
